local config = {
  ui_story_5040_50400101_1_dialog_content = "(อา... วันหยุดช่างยากเย็นเหลือเกิน...)",
  ui_story_5040_50400101_2_dialog_content = "(ไม่ ดึงตัวเองเข้าด้วยกัน!)",
  ui_story_5040_50400101_3_dialog_content = "\"(บี๊บ) 3 วันถึง <color=#FFB400>วันพระจันทร์เสี้ยว</color>\"",
  ui_story_5040_50400101_4_dialog_content = "\"วันไหว้พระจันทร์เป็นวันหยุดตามประเพณีในแอสตร้า เป็นวันสำหรับคู่รักที่จะแสดงความรักของพวกเขา และเป็นวันยอดนิยมสำหรับงานแต่งงาน\"",
  ui_story_5040_50400101_5_dialog_content = "ฉันรู้แล้ว! ถ้าฉันไม่ยุ่งมากจนพลาดไปเมื่อปีที่แล้ว ฉันคงไม่—",
  ui_story_5040_50400101_6_dialog_content = "ยังไงก็ตาม ฉันต้องซื้อเครื่องเล่นแผ่นเสียงนูนนั่นกลับมา ซึ่งเป็นเครื่องเล่นที่ Vice และ Carleen เล็งไว้ นั่นจะเป็นเซอร์ไพรส์วันหยุดที่ดี!",
  ui_story_5040_50400101_7_dialog_content = "(พวกเขาเพิ่งบอกว่าตั้งใจจะไปพักสั้นๆ และฉันไม่รู้ว่าพวกเขาหายไปไหน ยังไงก็ตาม ฉันแค่ต้องไปคนเดียวเท่านั้น!)",
  ui_story_5040_50400101_8_dialog_content = "PlayerName, สักพักหนึ่ง. มีอะไรให้ฉันช่วยไหม",
  ui_story_5040_50400101_9_dialog_content = "ขอโทษด้วย Courier Union ยุ่งกับเทศกาลที่กำลังจะมาถึง ฉันเลยไม่มีเวลาคุยจริงๆ",
  ui_story_5040_50400101_10_dialog_content = "ไม่ต้องพูดถึงเพื่อนร่วมงานของฉันในแผนก Rediesel Wrench ทำให้จดหมายหลายฉบับที่มุ่งหน้าไปยัง Lumopolis ยุ่งเหยิง...",
  ui_story_5040_50400101_11_dialog_content = "อะ... มีอะไรให้ช่วยไหม?",
  ui_story_5040_50400101_12_dialog_content = "ฉันต้องการซื้อของสำหรับวันหยุด ฉันจึงทำงานแปลก ๆ เพื่อหาเงิน",
  ui_story_5040_50400101_13_dialog_content = "ฉันไม่อยากรบกวนคุณอีก โดยเฉพาะเมื่อคุณช่วยทวีตตี้ครั้งที่แล้ว",
  ui_story_5040_50400101_14_dialog_content = "แต่จากที่คุณถาม มีสิ่งหนึ่ง คุณคิดว่าคุณสามารถแกว่งโดยแผนก Rediesel Wrench ได้หรือไม่?",
  ui_story_5040_50400101_15_dialog_content = "เพื่อนเก่าจาก Northland กำลังจะแต่งงานในวัน Mooncrown เช่นเดียวกับคนอื่นๆ",
  ui_story_5040_50400101_16_dialog_content = "เพียงแต่ว่าคู่หมั้นของเขาประสบอุบัติเหตุเล็กน้อยในทะเลทราย Rediesel เมื่อไม่นานมานี้ และพวกเขากังวลว่าจะมีเวลาไม่เพียงพอที่จะไปที่ Northland เมื่อเธอหายดีแล้ว",
  ui_story_5040_50400101_17_dialog_content = "และคุณต้องการยืม Colossus เพื่อให้แน่ใจว่าเธอไปถึงที่นั่นใช่ไหม? ไม่มีปัญหา ทำได้ง่ายๆ",
  ui_story_5040_50400101_18_dialog_content = "(พูดถึงงานแต่งงานของเพื่อน นาร็อกเซลจะไปเองไม่ใช่เหรอ?)",
  ui_story_5040_50400101_19_dialog_content = "(อย่างไรก็ตาม ควรสอบถามรายละเอียดจากผู้ที่เกี่ยวข้องเสมอ ซึ่งต้องเป็นแผนก Rediesel Wrench)",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>ก๊อกก๊อก-</color>",
  ui_story_5040_50400101_21_dialog_content = "ขอโทษทีนะ...",
  ui_story_5040_50400101_22_dialog_content = "คุณต้องเป็นคาเลสไทต์หนุ่มที่นี่เพื่อช่วย! ฉันรอคุณอยู่!",
  ui_story_5040_50400101_23_dialog_content = "ฉันคิดว่าคุณจะมาถึงเร็วกว่านี้ เหมือนที่ Naroxel พูดเสมอว่า Colossus เร็วแค่ไหน",
  ui_story_5040_50400101_X23_dialog_content = "(อ-งูตัวใหญ่อะไรอย่างนี้! เจ้าสิ่งนี้เป็นลำโพงเหรอ!? น่าทึ่งมาก!)",
  ui_story_5040_50400101_X24_dialog_content = "(และสำนักนี้... การกลั่นมักจะไม่ใช่สไตล์ประแจ Rediesel)",
  ui_story_5040_50400101_24_dialog_content = "(ว้าว สำนักนี้... การปรับแต่งมักไม่ใช่สไตล์ Rediesel Wrench)",
  ui_story_5040_50400101_25_dialog_content = "ยินดีที่ได้พบคุณ. ฉัน PlayerNameในนามของ Naroxel",
  ui_story_5040_50400101_26_dialog_content = "พวกคุณเป็นใคร?",
  ui_story_5040_50400101_27_dialog_content = "คุณอายุน้อยกว่าที่ฉันคิดไว้ อย่างไรก็ตาม ให้ฉันแนะนำตัวเอง",
  ui_story_5040_50400101_28_dialog_content = "ฉัน <color=#FFB400>เยริ</color>สมาชิกอาวุโสของแผนก Rediesel Wrench ของ Courier Union นี่คือ <color=#FFB400>ธารา</color>ลูกค้าของเราสำหรับการมอบหมายนี้",
  ui_story_5040_50400101_29_dialog_content = "สวัสดี ฉันทาร่า! ฉันไม่เคยคาดคิดว่าจะได้พบกับ Caeleste ในตำนาน สิ่งที่โชคดี!",
  ui_story_5040_50400101_30_dialog_content = "ฉันปลื้ม! คุณจะมากับเราที่ Northland ด้วยเหรอ Lady Jeriah?",
  ui_story_5040_50400101_31_dialog_content = "Jeriah เท่านั้นที่จะทำ เฮ้ มีเรื่องวุ่นวายกับจดหมาย และฉันไม่มีทางเลือกอื่นนอกจากขอความช่วยเหลือจาก Naroxel",
  ui_story_5040_50400101_32_dialog_content = "ดังนั้นฉันจะเป็นตัวแทนของเธอเป็นพยานในการแต่งงาน",
  ui_story_5040_50400101_33_dialog_content = "(ฉันสงสัยว่าเธอคือเพื่อนร่วมงานที่ Naroxel กล่าวถึงหรือไม่ว่าใครเป็นผู้รับผิดชอบเมลเคอร์ฟัฟเฟิล?)",
  ui_story_5040_50400101_34_dialog_content = "พยาน? ฉันได้ยินมาว่ามีคนจาก Courier Union เข้าร่วมงานแต่งงานจะนำความโชคดีมาสู่คู่บ่าวสาว",
  ui_story_5040_50400101_35_dialog_content = "แน่นอน! มันไม่ง่ายเลยที่จะหาคนส่งของสำหรับงานแต่งงานในวัน Mooncrown Naroxel ต้องขอความช่วยเหลือจากเราเท่านั้น!",
  ui_story_5040_50400101_36_dialog_content = "นาร็อกเซลยุ่งมากจนไม่มีวันหยุดเลยหรือ?",
  ui_story_5040_50400101_37_dialog_content = "ช่วงก่อนและหลังวัน Mooncrown มักจะคึกคักที่สุดสำหรับ Courier Union โดยมีคำเชิญและจดหมายทุกประเภทที่บินไปทั่ว",
  ui_story_5040_50400101_38_dialog_content = "จังหวะเหมาะที่ Jeriah ผู้น่ารัก \"บังเอิญ\" ทำพัสดุจำนวนมากที่มุ่งหน้าสู่ Northland เลอะเทอะ",
  ui_story_5040_50400101_39_dialog_content = "ฉันคิดว่าคุณเชิญเพื่อนชาว Caelestite มาที่นี่เพื่อเรื่องสำคัญมากกว่าที่จะเยาะเย้ยฉัน ไปกันเลย คุณไม่คิดถึงคู่หมั้นของคุณเหรอ?",
  ui_story_5040_50400101_40_dialog_content = "ความคิดที่ดี. เร็วที่สุดเท่าที่ Colossus อยู่ เราควรจะออกไปให้เร็วที่สุด",
  ui_story_5040_50400101_41_dialog_content = "ว้าว! ยักษ์ใหญ่ของคุณแตกต่างจากจิ้งจกยักษ์!",
  ui_story_5040_50400101_42_dialog_content = "ฮ่าๆ รอจนกว่าคุณจะได้ขึ้นเครื่อง",
  ui_story_5040_50400101_43_dialog_content = "อย่างไรก็ตาม เจ้าสาวในทะเลทรายและเจ้าบ่าวชาวนอร์ธแลนเดอร์เป็นคู่ที่น่าสนใจ สหภาพข้ามประเทศประเภทนี้มีอยู่ทั่วไปหรือไม่?",
  ui_story_5040_50400101_44_dialog_content = "อืม... บอกเลยว่าค่อนข้างหายาก!",
  ui_story_5040_50400101_45_dialog_content = "โลกเป็นสถานที่ที่กว้างใหญ่และทุกสิ่งเป็นไปได้ แต่สำหรับชาวออโรเรียนนั้นเป็นเรื่องแปลกเล็กน้อย",
  ui_story_5040_50400101_46_dialog_content = "โห จริงเหรอ",
  ui_story_5040_50400101_47_dialog_content = "แลด... Jeriah คุณมาจากทะเลทราย Rediesel เหมือนกันเหรอ?",
  ui_story_5040_50400101_48_dialog_content = "ไม่อยากยอมรับ แต่มันคือเรื่องจริง",
  ui_story_5040_50400101_49_dialog_content = "มันค่อนข้างแปลกที่คุณเกิดและเติบโตในทะเลทรายอย่างเห็นได้ชัด แต่คุณกลับไม่มีเพื่อนมากมายใน Rediesel Wrench",
  ui_story_5040_50400101_50_dialog_content = "ฉันต้องถามคนมากมายเพื่อหาสำนักงานของคุณ",
  ui_story_5040_50400101_51_dialog_content = "ตอนนี้ทุกคนต่างเดินตามเส้นทางของตัวเองในชีวิต",
  ui_story_5040_50400101_52_dialog_content = "อย่างไรก็ตามเรื่องราวชีวิตของฉันไม่สำคัญ คุณเป็นดาราของรายการในวันนี้",
  ui_story_5040_50400101_53_dialog_content = "ถูกตัอง! ไม่เคยเจอว่าที่เจ้าสาวมาก่อน!",
  ui_story_5040_50400101_54_dialog_content = "มันไม่ใช่เรื่องใหญ่อะไร พวกเราชาวทะเลทรายค่อนข้างใจกว้างเมื่อพูดถึงความรัก",
  ui_story_5040_50400101_55_dialog_content = "อย่างไรก็ตาม เรามีเวลาไม่มากนัก ฉันเลยอยากจะดูรอบๆ ยักษ์ใหญ่จริงๆ",
  ui_story_5040_50400101_56_dialog_content = "พาฉันไปเที่ยว PlayerName!",
  ui_story_5040_50400101_57_dialog_content = "อ่าโอเค. รอฉันด้วย!",
  ui_story_5040_50400101_58_dialog_content = "นี่อาจฟังดูแย่ แต่ทาราไม่ได้คิดว่าฉัน... เหมือนเจ้าสาวจริงๆ",
  ui_story_5040_50400101_59_dialog_content = "ทุกคนมีสไตล์เป็นของตัวเอง คาเลสไทต์ตัวน้อย นินทาลับหลังไม่ดี",
  ui_story_5040_50400101_60_dialog_content = "ใช่ ฉันคิดว่าคุณพูดถูก",
  ui_story_5040_50400101_61_dialog_content = "(Jeriah ดูไม่สนใจเรื่องงานแต่งงานเลย...)",
  ui_story_5040_50400101_62_dialog_content = "วุ้ย ในที่สุดเราก็มาถึงที่นี่",
  ui_story_5040_50400101_63_dialog_content = "Tara ออกไปหาคู่หมั้นของเธอหรือไม่? ฉันจำได้ว่าเคยเห็นสิ่งที่ดูเหมือนหมู่บ้านใกล้ๆ",
  ui_story_5040_50400101_64_dialog_content = "Origin Town บนชายแดนทางเหนือ คนส่วนใหญ่มีประเพณีและจัดพิธีแต่งงานในวัด",
  ui_story_5040_50400101_65_dialog_content = "เราควรไปที่นั่นไหม?",
  ui_story_5040_50400101_66_dialog_content = "ฉันคิดว่าสองคนนี้น่าจะอยู่ที่อื่นแล้วในตอนนี้",
  ui_story_5040_50400101_67_dialog_content = "(ตอนนี้ส่งลูกค้าไปแล้วต้องอยู่งานแต่งเองหรอ??)",
  ui_story_5040_50400101_68_dialog_content = "คุณกำลังสงสัยว่าคุณสามารถกลับไปตอนนี้ได้หรือไม่?",
  ui_story_5040_50400101_69_dialog_content = "(เธออ่านฉันเหมือนหนังสือ)",
  ui_story_5040_50400101_70_dialog_content = "เมื่อคุณเป็นเพื่อนของ Naroxel พวกเขาจะเชิญคุณไปงานแต่งงานอย่างไม่ต้องสงสัย",
  ui_story_5040_50400101_71_dialog_content = "คุณอยู่ที่นี่แล้ว แม้ว่างานแต่งงานใน Northland อาจไม่มีชีวิตชีวาเท่ากับงานแต่งงานใน Lumopolis แต่ก็มีเอกลักษณ์เป็นของตัวเอง",
  ui_story_5040_50400101_72_dialog_content = "จุดดี. อย่างไรก็ตาม ดูเหมือนคุณจะคุ้นเคยกับ Northland สำหรับคนที่มาจาก Rediesel Wrench Division",
  ui_story_5040_50400101_73_dialog_content = "ไม่ใช่แค่นอร์ธแลนด์! เธอรู้ทุกอย่างเกี่ยวกับโลก ยกเว้นเรื่องงาน",
  ui_story_5040_50400101_74_dialog_content = "ฮ่าฮ่าฮ่า คุณกลับมาแล้ว! เจ้าบ่าวอยู่ไหน?",
  ui_story_5040_50400101_75_dialog_content = "ธารา?",
  ui_story_5040_50400101_76_dialog_content = "ขอโทษที่ให้รอ...!",
  ui_story_5040_50400101_77_dialog_content = "คุณเป็นคนเชื่องช้าจริงๆ—",
  ui_story_5040_50400101_78_dialog_content = "นี่คือ Jeriah แห่ง Rediesel Wrench Division ของ Courier Union ฉันบอกคุณเกี่ยวกับเธอ",
  ui_story_5040_50400101_79_dialog_content = "และนี่คือคนที่พาเรามาที่นี่! พบปะ PlayerName, คาเลสไทต์! ยักษ์ใหญ่นั้นเป็นอะไรบางอย่างจริงๆ",
  ui_story_5040_50400101_80_dialog_content = "เขา <color=#FFB400>อิเหนา</color>คู่หมั้นของฉัน... เอ่อ มันค่อนข้างแปลกที่จะพูดแบบนั้น ฉันมักจะใช้ชื่อของเขา",
  ui_story_5040_50400101_81_dialog_content = "ยินดีที่ได้พบคุณทั้งสอง เลดี้ Jeriah PlayerName",
  ui_story_5040_50400101_82_dialog_content = "ขอโทษที่เร่งรีบในวันนี้ Naroxel เป็นเพื่อนเก่าของฉันสมัยเรียน เธอพร้อมช่วยเหลือเสมอในกรณีฉุกเฉิน",
  ui_story_5040_50400101_83_dialog_content = "ถ้าคุณให้เกียรติฉันในการเข้าร่วม PlayerNameเราอยากให้คุณมาร่วมงานแต่งงานด้วย",
  ui_story_5040_50400101_84_dialog_content = "อ๋อ ถึงบ้านยังคะ?",
  ui_story_5040_50400101_85_dialog_content = "เอ่อ ยังไม่ได้",
  ui_story_5040_50400101_86_dialog_content = "คุณยังไม่ได้บอกพวกเขา?",
  ui_story_5040_50400101_87_dialog_content = "คุณวางแผนที่จะลากสิ่งนี้ออกไปนานแค่ไหน?",
  ui_story_5040_50400101_88_dialog_content = "เพียงสองสามวัน! ฉันจะไปพรุ่งนี้ ฉันสัญญา!",
  ui_story_5040_50400101_89_dialog_content = "แล้วพรุ่งนี้ก็วันมะรืน! พรุ่งนี้ไม่มีวันมาถึง! คุณต้องการที่จะบอกพ่อแม่ของคุณหรือไม่?",
  ui_story_5040_50400101_90_dialog_content = "...",
  ui_story_5040_50400101_91_dialog_content = "(เกิดอะไรขึ้นที่นี่?)",
  ui_story_5040_50400101_92_dialog_content = "ดูเหมือนว่าเราจะพลาดเรื่องราวเบื้องหลังที่นี่",
  ui_story_5040_50400101_93_dialog_content = "ตั้งแต่เด็ก Caeleste และฉันถูกถามที่นี่ คุณไม่ควรแจ้งให้เราทราบว่าเกิดอะไรขึ้น?",
  ui_story_5040_50400101_94_dialog_content = "หืม คุณบอกพวกเขา!",
  ui_story_5040_50400101_95_dialog_content = "... คุณอาจพบว่าเรื่องนี้น่าขัน แต่พูดตามตรงว่า... เรากำลังมีพิธีลับเป็นการส่วนตัว",
  ui_story_5040_50400101_96_dialog_content = "พ่อแม่ของฉันไม่เคยต้องการให้ฉันแต่งงานกับธารา",
  ui_story_5040_50400101_97_dialog_content = "อา. ฉันเห็น.",
  ui_story_5040_50400101_98_dialog_content = "การแต่งงานระหว่างชาวเหนือกับชาวทะเลทรายนั้นค่อนข้างแปลก",
  ui_story_5040_50400101_99_dialog_content = "ฉันพูดจริงนะ คราวนี้ฉันจะบอกพวกเขา!",
  ui_story_5040_50400101_100_dialog_content = "แล้วออกไปจากที่นี่กันเถอะ! เราสามารถไปที่ Rediesel Desert หรือที่อื่นก็ได้",
  ui_story_5040_50400101_101_dialog_content = "คุณหมายถึงคุณกำลังหลบหนี?",
  ui_story_5040_50400101_102_dialog_content = "ฉันยินดีถ้าฉันสามารถโน้มน้าวพ่อแม่ของฉันได้ แต่...",
  ui_story_5040_50400101_103_dialog_content = "แต่อะไร? คุณยังไม่ได้ลอง",
  ui_story_5040_50400101_104_dialog_content = "เป็นเรื่องยากสำหรับคุณที่จะพูดด้วยตัวเอง?!",
  ui_story_5040_50400101_105_dialog_content = "ฉัน...",
  ui_story_5040_50400101_106_dialog_content = "ฉันสงสัยว่า Adonis คุณเคยออกจาก Northland มาก่อนหรือเปล่า",
  ui_story_5040_50400101_107_dialog_content = "N-ไม่มี ธาราและฉันพบกันที่นี่",
  ui_story_5040_50400101_108_dialog_content = "อา! ดอกไม้เรือนกระจกปรารถนาที่จะมีชีวิตเหมือนดอกไม้ป่า กล้าหาญแค่ไหน",
  ui_story_5040_50400101_109_dialog_content = "ฉันพร้อมแล้ว! ตราบใดที่คนสองคนยังอยู่ด้วยกัน ไม่มีอะไรที่เอาชนะไม่ได้!",
  ui_story_5040_50400101_110_dialog_content = "จริงหรือ แล้วการเอาชนะการไม่สามารถบอกพ่อแม่ของคุณล่ะ?",
  ui_story_5040_50400101_111_dialog_content = "เอ่อ ขอโทษที่ขัดจังหวะ...",
  ui_story_5040_50400101_112_dialog_content = "ฉันมีพัสดุสำหรับคุณอิเหนา คุณบอกว่ามันเป็นเรื่องด่วน ฉันเลยเอามาให้",
  ui_story_5040_50400101_113_dialog_content = "ทำไมถ้าไม่ใช่นกน้อยแห่งแดนเหนือล่ะ!",
  ui_story_5040_50400101_114_dialog_content = "แอล-เลดี้ เยริ?",
  ui_story_5040_50400101_115_dialog_content = "ขอบคุณสำหรับความช่วยเหลือของคุณในการคัดแยกจดหมายสองสามฉบับที่ส่งมาโดยบังเอิญ",
  ui_story_5040_50400101_116_dialog_content = "มันมากกว่าไม่กี่! โปรดใช้ความระมัดระวังในครั้งต่อไป",
  ui_story_5040_50400101_117_dialog_content = "<size=33>ฉันไม่ต้องการที่จะจัดการกับปริมาณงานที่น่าหวาดเสียวเช่นนี้อีกเลย...</size>",
  ui_story_5040_50400101_118_dialog_content = "ขอบคุณ, <color=#FFB400>คยา</color>.",
  ui_story_5040_50400101_119_dialog_content = "มันคือที่ไหนน่ะ?",
  ui_story_5040_50400101_120_dialog_content = "ใช่แล้ว ผู้มีพลังจิตที่ส่งยานี้บอกว่าให้ระมัดระวังในการใช้มัน เห็นได้ชัดว่ามันเป็นสิ่งที่ทรงพลังทีเดียว",
  ui_story_5040_50400101_121_dialog_content = "ยาพิษ? ยาอะไร?",
  ui_story_5040_50400101_122_dialog_content = "อ้อ เอ่อ... ไว้จะเล่าให้ฟังนะครับ",
  ui_story_5040_50400101_123_dialog_content = "แค่บอกฉันตอนนี้! พึมพำทั้งหมดของคุณคืออะไร!",
  ui_story_5040_50400101_124_dialog_content = "เฮ้อ...",
  ui_story_5040_50400101_125_dialog_content = "มันคือ <color=#FFB400>น้ำยาเอนกประสงค์</color> สร้างด้วยพลังจิตอาถรรพ์อันล้ำเลิศ สามารถใช้ช่วยเปลี่ยนสภาพจิตใจได้หลายวิธี เช่น เสริมความกล้า",
  ui_story_5040_50400101_126_dialog_content = "ฉันคิดว่ามันจะทำให้ฉันมีความมั่นใจมากขึ้นเมื่อติดต่อกับพ่อแม่ของฉัน",
  ui_story_5040_50400101_127_dialog_content = "(ฉันไม่เคยได้ยินเกี่ยวกับยาประเภทนี้มาก่อน!)",
  ui_story_5040_50400101_128_dialog_content = "หะ?! มีอะไรผิดปกติกับคุณ? คุณเชื่อเรื่องขยะจริง ๆ หรือไม่? ให้มันที่นี่ lemme ดู",
  ui_story_5040_50400101_129_dialog_content = "ฉันไม่อยากเชื่อเลยว่าทุกวันนี้ยังมีคนห่วยแตกที่ตกหลุมรักคนโรคจิต",
  ui_story_5040_50400101_130_dialog_content = "เราอยู่ด้วยกันมาสามปีแล้ว และคุณยังต้องพึ่งยาน้ำมันงูเพื่อบอกพ่อแม่ของคุณเกี่ยวกับเรา?",
  ui_story_5040_50400101_131_dialog_content = "ฉันได้รับสิ่งนี้เพื่อช่วยเรา!",
  ui_story_5040_50400101_132_dialog_content = "คุณเป็นคนขี้ขลาดขนาดนั้นจริงหรือ? หรือคุณมีความเชื่อในอนาคตของเราน้อยมาก?!",
  ui_story_5040_50400101_133_dialog_content = "อิเหนา เราจำเป็นต้องพึ่งพากำลังภายนอกอย่างจริงจังเพื่อรักษาความสัมพันธ์ของเราหรือไม่?",
  ui_story_5040_50400101_134_dialog_content = "ถ้าคุณต้องเป็นแบบนี้ อาจจะดีกว่าถ้าไม่—",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>ซวบ... ซวบ...</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>กรรรร!</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>แกร๊—!!</size>",
  ui_story_5040_50400101_138_dialog_content = "สุริยุปราคา? พวกเขามาจากไหน?",
  ui_story_5040_50400101_139_dialog_content = "Eclipsites มาทำอะไรที่นี่!",
  ui_story_5040_50400101_140_dialog_content = "นี่เป็นสิ่งที่ไม่คาดคิด ช่างน่ารำคาญ",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>...หวด!!!</color>",
  ui_story_5040_50400201_2_dialog_content = "กร๊าาาาซ—!",
  ui_story_5040_50400201_3_dialog_content = "กรา—!",
  ui_story_5040_50400201_4_dialog_content = "เกิดอะไรขึ้น? พวกเขามาจากไหน!",
  ui_story_5040_50400201_5_dialog_content = "แม้จะน่ารำคาญเช่นนี้ ก็ควรระวังไว้เป็นดีที่สุด",
  ui_story_5040_50400201_6_dialog_content = "มีบางอย่างแปลกเกี่ยวกับ Eclipsite ที่อยู่ตรงกลาง",
  ui_story_5040_50400201_7_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5040_50400201_8_dialog_content = "ธารา! ข้างหลังคุณ!",
  ui_story_5040_50400201_9_dialog_content = "อิเหนา ถอย! ให้เราจัดการเรื่องนี้!",
  ui_story_5040_50400201_10_dialog_content = "ระวังทาร่า! Eclipsite ประหลาดนั่นดูเหมือนจะเล็งมาที่คุณแล้ว!",
  ui_story_5040_50400201_11_dialog_content = "ให้...",
  ui_story_5040_50400201_12_dialog_content = "ให้...ฉัน...",
  ui_story_5040_50400201_13_dialog_content = "อยาก...อยาก...",
  ui_story_5040_50400201_14_dialog_content = "เธอว่าไงนะ",
  ui_story_5040_50400201_15_dialog_content = "(มันกำลังพูดเรื่อง Universese?)",
  ui_story_5040_50400201_16_dialog_content = "ธารา! กำจัดยาในมือของคุณ!",
  ui_story_5040_50400201_17_dialog_content = "วะ—",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>หวือ— สแลม!</color>",
  ui_story_5040_50400201_19_dialog_content = "ธารา!!",
  ui_story_5040_50400201_20_dialog_content = "สิ่งนี้เป็นอันตราย หาที่กำบัง!",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>ตูมซ่า...</color>",
  ui_story_5040_50400201_22_dialog_content = "เอ๊ะ!",
  ui_story_5040_50400201_23_dialog_content = "ฮึ่ม...! น้ำยา...",
  ui_story_5040_50400201_24_dialog_content = "กรร...",
  ui_story_5040_50400201_25_dialog_content = "เกร๋! กราาาาาา!",
  ui_story_5040_50400201_27_dialog_content = "พวกเขาเพิ่งออกไปหรือไม่?",
  ui_story_5040_50400201_28_dialog_content = "ยังเหลือตัวเล็กๆ อีกหลายตัว",
  ui_story_5040_50400201_29_dialog_content = "ดูแลคู่หมั้นของคุณอิเหนา",
  ui_story_5040_50400202_1_dialog_content = "ในที่สุด. ทุกคนสบายดีไหม",
  ui_story_5040_50400202_2_dialog_content = "ธารา! ธารา!!",
  ui_story_5040_50400202_3_dialog_content = "ไม่นะ! เธอหนาว!",
  ui_story_5040_50400202_4_dialog_content = "คุณสองคนออกไปให้พ้นทาง ขอฉันดูหน่อย.",
  ui_story_5040_50400202_5_dialog_content = "ไม่มีบาดแผลร้ายแรง ดูเหมือนว่า Eclipsite จะไม่ทำร้ายเธอมากนัก",
  ui_story_5040_50400202_6_dialog_content = "เพียงไม่กี่รอยขีดข่วน",
  ui_story_5040_50400202_7_dialog_content = "แต่ทำไมเธอถึงสลบไปล่ะ? เธออาจจะโดนหัวของเธอ?",
  ui_story_5040_50400202_8_dialog_content = "ก่อนอื่นให้สงบสติอารมณ์ ตอนนี้ดูเหมือนเธอสบายดี แต่เราต้องพาเธอไปในที่ที่ปลอดภัย",
  ui_story_5040_50400202_9_dialog_content = "อืม ดูเหมือนว่าเธอจะได้รับยาพิษบางอย่างกับเธอ",
  ui_story_5040_50400202_10_dialog_content = "ไม่มีอะไรเลวร้ายเลยใช่ไหม!",
  ui_story_5040_50400202_11_dialog_content = "ฉันไม่รู้! คุณเป็นคนต้องการมัน อิเหนา! ฉันแค่ส่งมันในนามของผู้มีพลังจิตคนนั้น",
  ui_story_5040_50400202_12_dialog_content = "อย่าให้ตัวเองทำงาน สิ่งที่สำคัญที่สุดในตอนนี้คือการพาเธอไปพักผ่อน",
  ui_story_5040_50400202_13_dialog_content = "ใช่. ฉันขอโทษสำหรับปัญหาทุกคน เราช่วยพาเธอไปที่บ้านของฉันได้ไหม",
  ui_story_5040_50400202_14_dialog_content = "เอาล่ะ ฉันจะออกไปส่งของที่เหลือให้เสร็จ ดูแลทาร่า พวกคุณ",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก ก๊อก!</color>",
  ui_story_5040_50400202_16_dialog_content = "อิเหนา? คุณรู้ไหมว่ากี่โมงแล้ว—",
  ui_story_5040_50400202_17_dialog_content = "นี่คืออะไร? เกิดอะไรขึ้น?!",
  ui_story_5040_50400202_18_dialog_content = "เรื่องมันยาวนะพ่อ ให้เราเข้ามาก่อน",
  ui_story_5040_50400202_19_dialog_content = "นี่เพื่อนของเธอเหรอ อิเหนา? แล้วเธอคนนี้...คือทาร่ารึเปล่า?",
  ui_story_5040_50400202_20_dialog_content = "ขออภัยในความไม่สะดวก.",
  ui_story_5040_50400202_21_dialog_content = "เธอเจ็บนะแม่ เราเจอ Eclipsites บางแห่ง... เราช่วยเธอให้สงบก่อนได้ไหม? แล้วฉันจะเล่าเรื่องทั้งหมดให้คุณฟัง",
  ui_story_5040_50400202_22_dialog_content = "สุริยุปราคา?! เราควรมีชุดปฐมพยาบาลไว้ที่ใดที่หนึ่ง มีแผลที่ต้องดูแลไหม? เจ็บมั้ย!",
  ui_story_5040_50400202_23_dialog_content = "ไม่มีเหตุให้ต้องตื่นตระหนก เธอมีบาดแผลถลอกเล็กน้อยและน่าจะช็อก คนอื่นๆ สบายดี",
  ui_story_5040_50400202_24_dialog_content = "ฉันจะไปดูแลเธอ พวกคุณคุยกัน",
  ui_story_5040_50400202_25_dialog_content = "นั่นคือสิ่งที่เกิดขึ้น ...",
  ui_story_5040_50400202_26_dialog_content = "น่าสมเพช!",
  ui_story_5040_50400202_27_dialog_content = "คุณจะไม่บอกแม่และฉันเกี่ยวกับเรื่องนี้ได้อย่างไร?",
  ui_story_5040_50400202_28_dialog_content = "ถ้าเธอไม่ได้รับบาดเจ็บ คุณก็แค่หนีออกจากนอร์ธแลนด์งั้นเหรอ?",
  ui_story_5040_50400202_29_dialog_content = "ฉัน...",
  ui_story_5040_50400202_30_dialog_content = "ฉันเคยคิดว่าคุณเป็นคนงี่เง่า แต่ฉันไม่คิดว่าคุณงี่เง่าสิ้นดี!",
  ui_story_5040_50400202_31_dialog_content = "ทุกสิ่งที่ Novio สอนคุณเพียงแค่ใส่หูข้างเดียวและออกอีกข้างหนึ่ง?!",
  ui_story_5040_50400202_32_dialog_content = "คุณคิดว่าคุณสามารถไปด้วยตัวเองได้จริงๆ ถ้าคุณออกจาก Northland? งั้นก็ได้ ไป! และไม่กลับมาอีก!",
  ui_story_5040_50400202_33_dialog_content = "เราจะทำเป็นว่าเราไม่เคยมีลูกชาย!",
  ui_story_5040_50400202_34_dialog_content = "พ่อ แม่ ได้โปรด... ฉันไม่ได้หมายความอย่างนั้น!",
  ui_story_5040_50400202_35_dialog_content = "บันทึกข้อแก้ตัวที่น่าสมเพชของคุณ ฉันไม่อยากได้ยินอะไรทั้งนั้น!",
  ui_story_5040_50400202_36_dialog_content = "พ่อคุณแค่โกรธนะลูก",
  ui_story_5040_50400202_37_dialog_content = "แต่จริงๆ อิเหนา เราหมดปัญญากับคุณแล้ว",
  ui_story_5040_50400202_38_dialog_content = "...",
  ui_story_5040_50400202_39_dialog_content = "เอ่อ...",
  ui_story_5040_50400202_40_dialog_content = "(... บอกไม่ได้ว่าเคยเห็นอะไรแบบนี้มาก่อน)",
  ui_story_5040_50400202_41_option_content = "ความสะดวกสบายอิเหนา",
  ui_story_5040_50400202_42_dialog_content = "อย่าเก็บมาใส่ใจ พวกเขาแค่อารมณ์เสียเล็กน้อย",
  ui_story_5040_50400202_43_dialog_content = "ฉันหมายความว่าเป็นเรื่องปกติที่พวกเขาจะมีอารมณ์เล็กน้อย เมื่อได้ยินทั้งหมดนี้ในทันใด",
  ui_story_5040_50400202_44_dialog_content = "แต่พวกเขายังคงเป็นพ่อแม่ของคุณ ค่อยคุยกันทีหลัง และฉันมั่นใจว่าทุกอย่างจะเรียบร้อย",
  ui_story_5040_50400202_45_dialog_content = "เฮ้อ... พ่อแม่ไม่ยอมยกโทษให้ฉัน และทาร่าก็เจ็บปวดเหมือนกัน",
  ui_story_5040_50400202_46_dialog_content = "ฉันเป็นคนที่ล้มเหลวจริงๆ",
  ui_story_5040_50400202_47_dialog_content = "(ไม่ดีแน่ เหมือนเขาจะจมอยู่ในวงจรของการคิดลบเกี่ยวกับตัวเอง...)",
  ui_story_5040_50400202_48_option_content = "ขอความช่วยเหลือจาก Jeriah",
  ui_story_5040_50400202_49_dialog_content = "เราควรทำอย่างไร เยรียาห์?",
  ui_story_5040_50400202_50_dialog_content = "หา? อะไรเหรอ?",
  ui_story_5040_50400202_51_dialog_content = "(เธอเว้นระยะห่างหรือเปล่า? ในเวลาแบบนี้?!)",
  ui_story_5040_50400202_52_dialog_content = "คุณพูดอะไรในสถานการณ์เหล่านี้",
  ui_story_5040_50400202_53_dialog_content = "นี่คือปัญหาของเขา ไม่สำคัญว่าคนอื่นจะพูดอะไร",
  ui_story_5040_50400202_54_dialog_content = "อย่างไรก็ตาม แม้ว่าคุณจะเสนอคำพูดซ้ำๆ ซากๆ สักเล็กน้อย แต่ก็ไม่ได้ช่วยแก้ปัญหาอะไรเลย",
  ui_story_5040_50400202_55_dialog_content = "(เธอไม่ผิด แต่แน่นอนว่าฉันไม่สามารถพูดอะไรได้เลย!)",
  ui_story_5040_50400202_56_dialog_content = "(นี่มันน่าอึดอัดจัง... บรรยากาศเคร่งขรึมและอึดอัดมาก)",
  ui_story_5040_50400202_57_dialog_content = "ฉันขอโทษจริงๆ ฉันนึกไม่ออกว่าคุณต้องคิดอย่างไร",
  ui_story_5040_50400202_58_dialog_content = "ไม่เป็นไร เพียงแจ้งให้เราทราบหากมีอะไรที่เราสามารถช่วยได้",
  ui_story_5040_50400202_59_dialog_content = "เอ่อ... ฉันยกมาทั้งหมดเอง",
  ui_story_5040_50400202_60_dialog_content = "คุณมาไกลมากเหมือนกัน และฉันก็เป็นเจ้าภาพที่แย่มาก",
  ui_story_5040_50400202_61_dialog_content = "ไม่ต้องกังวลเกี่ยวกับเรื่องนั้นในตอนนี้",
  ui_story_5040_50400202_62_dialog_content = "ทำไมคุณไม่พาเขาออกไปเพื่อล้างหัวของเขา PlayerName? ฉันจะดูแลธารา",
  ui_story_5040_50400202_63_dialog_content = "ตกลง. ไปสูดอากาศบริสุทธิ์กันเถอะ",
