  ui_story_5040_50400202_66_dialog_content = "ฉันคิดว่าถึงเวลาที่คุณตื่นแล้ว",
  ui_story_5040_50400202_67_dialog_content = "?!",
  ui_story_5040_50400202_68_dialog_content = "คุณรู้ได้อย่างไรว่าฉันตื่นแล้ว",
  ui_story_5040_50400202_69_dialog_content = "Eclipsite นั้นไม่ได้โจมตีคุณจริงๆ",
  ui_story_5040_50400202_70_dialog_content = "ฉันสงสัยมากว่าคุณคงหมดสติไปนาน",
  ui_story_5040_50400202_71_dialog_content = "...",
  ui_story_5040_50400202_72_dialog_content = "ฉันมาที่นี่เพื่อช่วยนาร็อกเซลเท่านั้น ดังนั้นฉันจะไม่เสียเวลามากเกินไป",
