  ui_story_5040_50400202_74_dialog_content = "แต่เนื่องจากฉันช่วยอะไรเธออยู่ ฉันเลยลองถามดู คุณวางแผนที่จะทำอะไร?",
  ui_story_5040_50400202_75_dialog_content = "ฉัน...",
  ui_story_5040_50400202_76_dialog_content = "สุจริต? ฉันไม่รู้. ชีวิตในทะเลทรายไม่เคยยุ่งยากเช่นนี้มาก่อน ฉันรำคาญมาก",
