  ui_story_5040_50400202_78_dialog_content = "อุปนิสัยของใครบางคนไม่สามารถเกิดขึ้นและไม่สามารถเปลี่ยนแปลงได้ในชั่วข้ามคืน อยู่ด้วยกันมานาน เพิ่งค้นพบปัญหานี้จริงๆ เหรอ?",
