  ui_story_5040_50400202_80_dialog_content = "เมื่อสามปีก่อน ฉันถูก Eclipsites โจมตีขณะค้นหาซากปรักหักพังใน Northland ฉันพยายามหนีแต่เป็นลมหมดสติอยู่ข้างถนน",
