  ui_story_5040_50400202_82_dialog_content = "*ถอนหายใจ* หลังจากนั้นเราก็คุยกันทุกเรื่องเกี่ยวกับสิ่งที่อีกฝ่ายไม่เคยเห็น",
  ui_story_5040_50400202_83_dialog_content = "เราติดต่อกันหลังจากที่ฉันกลับไปที่ทะเลทราย ส่งจดหมายไปมา",
