  ui_story_5040_50400202_88_dialog_content = "เขาไม่เหมือนเดิม ทำใจยากขนาดนั้นเลยเหรอ?",
  ui_story_5040_50400202_89_dialog_content = "ฉันไม่เคยเจอผู้ชายขี้อาย เด็ดขาดขนาดนี้มาก่อน! เขาชอบฉันจริงๆเหรอ?",
  ui_story_5040_50400202_90_dialog_content = "ฉันวางแผนงานแต่งงานของเรามานานแล้ว และเตรียมของขวัญสุดพิเศษไว้ให้ด้วย แต่ตอนนี้... เอิ่ม",
  ui_story_5040_50400202_91_dialog_content = "มันคงไม่เหมาะสม แต่คุณเคยรักเขามาก่อนหรือเปล่า?",
