  ui_story_5040_50400202_94_dialog_content = "ความรักเป็นสิ่งสวยงาม แต่คุณต้องเคารพใครคนนั้นด้วย แต่ละคนเป็นสิ่งมีชีวิตที่ซับซ้อนและเหมาะสมยิ่ง ไม่มีใครเป็นแค่ขาวหรือดำ",
