  ui_story_5040_50400202_134_dialog_content = "(ฉันไม่ค่อยเข้าใจเรื่องของหัวใจ สิ่งต่าง ๆ อาจแย่กว่านี้ถ้าฉันสอดรู้สอดเห็น ดังนั้น อย่าเพิ่งเข้าไปยุ่งในตอนนี้)",
