  ui_story_5040_50400202_136_dialog_content = "ยาพิษนั่น! ฉันหวังว่าฉันจะไม่เคยคิดเลยด้วยซ้ำ!",
  ui_story_5040_50400202_137_dialog_content = "คุณคิดว่ายานี้มีส่วนทำให้ความจำเสื่อมของเธอเหรอ?",
  ui_story_5040_50400202_138_dialog_content = "พลังจิตบอกว่าสามารถสร้างเอฟเฟกต์ได้ทุกชนิด! ฉันไม่สามารถคิดถึงเหตุผลอื่นสำหรับสิ่งนี้!",
  ui_story_5040_50400202_139_dialog_content = "มันต้องเป็นอย่างนั้น ยาพิษหกใส่เธอ ตอนที่เธอรำคาญฉันและอยากให้เธอลืมทุกอย่างเกี่ยวกับฉัน! นั่นคือสิ่งที่ยาทำ!",
  ui_story_5040_50400202_140_dialog_content = "มันเป็นความผิดของฉันทั้งหมด!",
  ui_story_5040_50400202_141_dialog_content = "ถ้าเป็นเช่นนั้นจริงทำไมไม่ไปถามจิต",
  ui_story_5040_50400202_142_dialog_content = "ไม่มีประโยชน์ที่จะมานั่งร้องไห้เพราะนมหก",
  ui_story_5040_50400202_143_dialog_content = "กายสิทธิ์?",
  ui_story_5040_50400202_144_dialog_content = "ใช่คุณพูดถูก! และฉันเพิ่งนึกขึ้นได้ว่าบางครั้งพวกเขาตั้งแผงขายของในตลาด!",
  ui_story_5040_50400202_145_dialog_content = "ฉันจะไป! ฉันจะไปเดี๋ยวนี้แหละ!",
  ui_story_5040_50400202_146_dialog_content = "*หอบ*... O-ตรงนั้น!",
  ui_story_5040_50400202_147_dialog_content = "(ว้าว เขาวิ่งเร็วมาก...)",
  ui_story_5040_50400202_148_dialog_content = "อืม? คุณอาจเป็นใคร",
  ui_story_5040_50400202_149_dialog_content = "ฉันเป็นคนซื้อยาวิเศษนั่น! ฉันมีคำถามเร่งด่วนสำหรับคุณ!",
  ui_story_5040_50400202_150_dialog_content = "ฮะ...? โอ้ใช่! เจ้านั่น!",
  ui_story_5040_50400202_151_dialog_content = "มันเป็นอย่างไร? ฉันทุ่มเทแรงกายแรงใจให้กับขวดแต่ละขวด ฉันจึงเชื่อมั่นว่าผลลัพธ์จะเป็นอย่างที่คาดหวังไว้?",
  ui_story_5040_50400202_152_dialog_content = "เรื่องมันยาว แต่คู่หมั้นของฉันใช้ยานี้โดยไม่ได้ตั้งใจ และตอนนี้เธอจำอะไรไม่ได้เลย! ได้โปรด คุณต้องให้ยาแก้พิษแก่ฉัน!",
  ui_story_5040_50400202_153_dialog_content = "ฮะ?! แต่นั่นเป็นไปไม่ได้...",
  ui_story_5040_50400202_154_dialog_content = "คุณไม่ได้บอกว่ามันสามารถทำอะไรได้เหรอ? ตามใจปรารถนา?!",
  ui_story_5040_50400202_155_dialog_content = "ฉันพูดอย่างนั้นใช่",
  ui_story_5040_50400202_156_dialog_content = "แต่ถ้าเป็นยาแก้พิษที่คุณต้องการ... ฉันเกรงว่าอาจต้องใช้ความพยายามสักหน่อย",
  ui_story_5040_50400202_157_dialog_content = "ฮะ? มาได้ไง!",
  ui_story_5040_50400202_158_dialog_content = "เพราะมันสร้างจากสิ่งที่น้อยคนนักจะเคยเห็น สมบัติที่หายากที่สุดของ Rediesel Desert เกล็ดแวววาวของหนอนทรายสีชมพูในตำนาน!",
  ui_story_5040_50400202_159_dialog_content = "ฉันมาจากทะเลทรายเอง ทำไมฉันไม่เคยได้ยินเรื่องนี้มาก่อน?",
  ui_story_5040_50400202_160_dialog_content = "!",
  ui_story_5040_50400202_161_dialog_content = "บอกข้าที... หากพวกเจ้าสามัญชนรู้เรื่องนี้ทั้งหมด มันจะยังหายากอยู่อีกหรือ?",
  ui_story_5040_50400202_162_dialog_content = "คนส่วนใหญ่จะไม่เคยเห็นหนอนทรายสีชมพูลึกลับเลยแม้แต่ครั้งเดียวในชีวิต",
  ui_story_5040_50400202_163_dialog_content = "(ฉันว่าพลังจิตนี่มีเต็มเปี่ยม แล้วใครล่ะจะอยากเห็นของแบบนั้นกันล่ะ?)",
  ui_story_5040_50400202_164_dialog_content = "เกล็ดของมันระยิบระยับด้วยสายรุ้งทุกสี ในขณะที่ตัวสีชมพูของมันช่างงดงามและพร่างพราวราวกับเปลือกที่สวยงามที่สุด!",
  ui_story_5040_50400202_165_dialog_content = "หากคุณยืนยันในยาแก้พิษนี้ ก็จะไม่สามารถทำได้หากไม่มีเกล็ดของมัน บางทีคุณควรคิดวิธีรับบ้าง!",
  ui_story_5040_50400202_166_dialog_content = "Y-คุณจงใจทำให้เรื่องยุ่งยากใช่ไหม!",
  ui_story_5040_50400202_167_dialog_content = "เฮ้ ฉันไม่ใช่คนที่ต้องการยาแก้พิษ ฉันบอกคุณด้วยความหวังดี ปล่อยฉันเดี๋ยวนี้ ฉันไม่ต้องการให้คุณมีผลกระทบกับธุรกิจของฉัน",
  ui_story_5040_50400202_168_dialog_content = "...",
  ui_story_5040_50400202_169_dialog_content = "แค่นั้นแหละ. มันจบแล้ว.",
  ui_story_5040_50400202_170_dialog_content = "เต็มใจและทำได้ทุกอย่าง แต่จะสู้หนอนทราย...? เป็นไปไม่ได้.",
  ui_story_5040_50400202_171_dialog_content = "แม้แต่หนอนในสวนของฉันยังทำให้ฉันกลัว ไม่มีทางที่ฉันจะไปหาหนอนทรายทะเลทรายได้!",
  ui_story_5040_50400202_172_dialog_content = "รู้ไหม... ฉันไม่ค่อยเจอผู้ชายที่กระดูกสันหลังน้อยอย่างคุณ",
  ui_story_5040_50400202_173_dialog_content = "(โปรดอย่าทำให้มันแย่ลง!)",
  ui_story_5040_50400202_174_dialog_content = "มองในด้านสว่าง อย่างน้อยเธอก็ยังมีชีวิตอยู่และมีสุขภาพดี และจากสิ่งที่ฉันเข้าใจ เธอเพิ่งสูญเสียความทรงจำเกี่ยวกับความสัมพันธ์ของคุณ",
  ui_story_5040_50400202_175_dialog_content = "แทนที่จะไปไล่ล่าห่านป่า บางทีมันอาจจะดีกว่าที่จะคิดถึงวิธีจุดไฟโรแมนติกนั้นอีกครั้ง",
  ui_story_5040_50400202_176_dialog_content = "และยังไงก็ตาม เธอยังไม่ลืมทุกอย่าง ตราบใดที่เธอไม่เป็นไร ก็ยังมีโอกาส",
  ui_story_5040_50400202_177_dialog_content = "ต้องมีเหตุผลที่คุณสองคนอยู่ด้วยกันมานาน ฉันไม่คิดว่ามันควรจะยากเกินไปที่จะเริ่มต้นใหม่ อย่างที่เคยเป็นมา",
  ui_story_5040_50400202_178_dialog_content = "ใช่... ฉันคิดว่าคุณพูดถูก",
  ui_story_5040_50400202_179_dialog_content = "ประเด็นคือ ฉันไม่มีความคิดที่เฉียบคมที่สุดว่าจะเริ่มจากตรงไหนดี เธอเห็นฉันเป็นคนแปลกหน้าโดยสิ้นเชิง",
  ui_story_5040_50400202_180_dialog_content = "อย่างไรก็ตาม ฉันแน่ใจว่าคุณทั้งคู่จำได้ว่าฉันถูกส่งมาที่นี่เพื่อร่วมงานแต่งงานในนามของนาร็อกเซล",
  ui_story_5040_50400202_181_dialog_content = "ผู้คนจำนวนมากแต่งงานกันในวัน Mooncrown และส่วนใหญ่ต้องการคนส่งของเพื่อเข้าร่วมงานแต่งงานของพวกเขา",
  ui_story_5040_50400202_182_dialog_content = "ฉันเคยได้ยินเกี่ยวกับประเพณีนั้น เห็นได้ชัดว่าการมีคนส่งของในงานแต่งงานของคุณสามารถนำพาความสุขและความหวังมาให้ได้",
  ui_story_5040_50400202_183_dialog_content = "จับได้เห็นชัดตรงเผง. นั่นเป็นเหตุผลที่สหภาพจัดงานวัน Mooncrown พิเศษในช่วงไม่กี่ปีที่ผ่านมา โดยมุ่งเป้าไปที่คู่บ่าวสาวและคู่บ่าวสาว",
  ui_story_5040_50400202_184_dialog_content = "นอกจากนี้ยังช่วยลดแรงกดดันต่อผู้จัดส่ง เป็นหนึ่งในช่วงเวลาที่คึกคักที่สุดของปี",
  ui_story_5040_50400202_185_dialog_content = "จริงหรือ ฉันไม่เคยรู้ว่า",
  ui_story_5040_50400202_186_dialog_content = "ใช่ ชัดเจน เพราะพวกเขามุ่งเป้าไปที่คู่รัก ฉันสงสัยเป็นอย่างยิ่งว่าพวกเขาจะอยู่ในเรดาร์ของคนโสดตลอดกาล",
  ui_story_5040_50400202_187_dialog_content = "อ๊ะ!",
  ui_story_5040_50400202_188_dialog_content = "คุณกำลังทำอะไรอยู่?",
  ui_story_5040_50400202_189_dialog_content = "ในไม่กี่แห่ง เหตุการณ์นี้ได้เข้ามาแทนที่ประเพณีการส่งของไปร่วมงานแต่งงานแล้วเพื่อเป็นการอวยพรให้คู่รักมีความสุข",
  ui_story_5040_50400202_190_dialog_content = "แต่ละสาขาจะมีกิจกรรมของตัวเอง และผู้ที่ประสบความสำเร็จจะได้รับตราขนนกของ Courier Union",
  ui_story_5040_50400202_191_dialog_content = "คุณควรพิจารณาเข้าร่วมกิจกรรมเหล่านี้กับธารา คุณจะได้ออกไปสำรวจโลกภายนอกในขณะที่คุณอยู่ที่นั่น",
  ui_story_5040_50400202_192_dialog_content = "คุณหมายถึง... ออกจาก Northland เหรอ?",
  ui_story_5040_50400202_193_dialog_content = "คนความจำเสื่อมมักจะมีความทรงจำในอดีตที่ปั่นป่วนจากเหตุการณ์ภายนอก นั่นเป็นวิธีการรักษาพื้นบ้านแบบเก่า",
  ui_story_5040_50400202_194_dialog_content = "ทั้งหมดที่ฉันพูดคือกิจกรรม Courier Union อาจเป็นโอกาสที่ดี คุณจะทำอะไรกับมันขึ้นอยู่กับคุณ",
  ui_story_5040_50400202_195_dialog_content = "คุณจะไม่ประสบความสำเร็จมากนักจากการปิดตัวเองและกังวลที่บ้าน ถ้าไม่ออกไปดูโลกจะรู้ได้อย่างไรว่ามีทางแก้?",
  ui_story_5040_50400202_196_dialog_content = "ไม่ใช่เรื่องของฉัน แต่ใครจะบอกว่าคุณอาจไม่ค้นพบวิธีที่จะทำให้ความทรงจำของเธอกลับมาโดยการออกไปท่องเที่ยว?",
  ui_story_5040_50400202_197_dialog_content = "ฉันเห็นด้วย!",
  ui_story_5040_50400202_198_dialog_content = "ก่อนหน้านี้ฉันเคยอยู่อย่างสันโดษคนเดียวเป็นเวลานาน ทุกสิ่งที่ฉันรู้เกี่ยวกับโลกถูกสอนให้ฉัน",
  ui_story_5040_50400202_199_dialog_content = "เมื่อฉันออกไปเท่านั้นที่ฉันรู้ว่าโลกกว้างมีอะไรมากมายที่ฉันไม่รู้อะไรเลย",
  ui_story_5040_50400202_200_dialog_content = "หากคุณออกไปสำรวจ คุณอาจเขย่าความทรงจำของ Tara และเรียนรู้เพิ่มเติมเกี่ยวกับอาการของเธอ!",
  ui_story_5040_50400202_201_dialog_content = "พวก...!",
