  ui_story_5040_50400202_230_dialog_content = "ผู้ที่ไม่แข็งแกร่งเท่าคนอื่นจะไม่ไขว่คว้าหาความสุขอย่างแข็งขัน แต่จะรับมันไว้อย่างเฉยเมย",
