  ui_story_5040_50400301_38_dialog_content = "ฉัน... ไม่... โจมตี...",
  ui_story_5040_50400301_39_dialog_content = "ต้องการ...ยา...",
  ui_story_5040_50400301_40_dialog_content = "ยาพิษ?",
  ui_story_5040_50400301_41_dialog_content = "ฉัน... ซ่อน... ตลาด...",
  ui_story_5040_50400301_42_dialog_content = "สดับ...ยา...อานุภาพ...",
  ui_story_5040_50400301_43_dialog_content = "ต้องการ... ใช้... ฟื้นฟู... ความจำ...",
  ui_story_5040_50400301_44_dialog_content = "แต่... พวกเขา... เอา...",
  ui_story_5040_50400301_45_dialog_content = "นั่นคือสิ่งที่เกิดขึ้น",
  ui_story_5040_50400301_46_dialog_content = "แต่ Eclipsite จะมีความทรงจำได้อย่างไร? คุณเคยเป็น Aurorian มาก่อนได้ไหม?",
  ui_story_5040_50400301_47_dialog_content = "คิด...ก็...แต่...ลืม...",
  ui_story_5040_50400301_48_dialog_content = "ฉันกลัว...",
  ui_story_5040_50400301_49_dialog_content = "(ทุกคนดูถูก Eclipsites แต่ดูเหมือนว่าจะไม่โกหก...)",
  ui_story_5040_50400301_50_dialog_content = "(ถ้าใครรู้ว่าฉันกำลังช่วย Eclipsite ฉันคงตกงานเป็นคนส่งของแน่ ฉันอาจถูกจับด้วยซ้ำ)",
  ui_story_5040_50400301_51_dialog_content = "หนาวนิดหน่อยน่ะ...",
  ui_story_5040_50400301_52_dialog_content = "มันคือ!",
  ui_story_5040_50400301_53_dialog_content = "ใช้ได้. มาเลย",
  ui_story_5040_50400301_54_dialog_content = "ขอบคุณ...!",
  ui_story_5040_50400301_55_dialog_content = "เพื่อให้เราชัดเจน เรื่องตลกใดๆ และฉันกำลังแจ้งเตือนผู้พูด!",
  ui_story_5040_50400301_56_dialog_content = "ได้เลยค่ะ",
  ui_story_5040_50400301_57_dialog_content = "ใช่แล้วตอนนี้ ... ?",
  ui_story_5040_50400301_58_dialog_content = "ซ่อนที่นี่อีกสักหน่อย",
  ui_story_5040_50400301_59_dialog_content = "ใช่มันควรจะใช้งานได้!",
  ui_story_5040_50400301_60_dialog_content = "ให้ฉัน...?",
  ui_story_5040_50400301_61_dialog_content = "คุณแน่ใจหรือว่าต้องการใส่ชุดนี้? มันเป็นชุดเพื่อนเจ้าสาวเก่าของฉัน",
  ui_story_5040_50400301_62_dialog_content = "คุณดูเหมือน Aurorian ในนั้น แม้ว่าชุดจะโดดเด่นไปหน่อย",
  ui_story_5040_50400301_63_dialog_content = "ขอบคุณ... คุณ... แต่งตัว... ดี...",
  ui_story_5040_50400301_64_dialog_content = "ช่างเถอะ. ถ้าชอบก็ใส่ได้ ฉันชื่อคยา อย่างไรก็ตาม ฉันควรเรียกคุณว่าอะไรในที่สาธารณะ? คุณจำชื่อของคุณได้ไหม?",
  ui_story_5040_50400301_65_dialog_content = "อย่า...รู้...",
  ui_story_5040_50400301_66_dialog_content = "ฉันคิดว่าฉันจะโทรหาคุณ Sable ในตอนนี้ วิธีที่ว่า?",
  ui_story_5040_50400301_67_dialog_content = "ก็... ก็ได้...",
  ui_story_5040_50400301_68_dialog_content = "คุณจำอะไรไม่ได้เลยจริงๆเหรอ?",
  ui_story_5040_50400301_69_dialog_content = "เปล่านะ...",
  ui_story_5040_50400301_70_dialog_content = "คุณเคยอยู่ที่นอร์ธแลนด์หรือเปล่า?",
  ui_story_5040_50400301_71_dialog_content = "ไม่สิ...คิดว่า...มาจาก...แดนไกล...",
  ui_story_5040_50400301_72_dialog_content = "อืม โอเค ขอคิดก่อนนะ.",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>วันถัดไป-</color>",
  ui_story_5040_50400301_74_dialog_content = "พร้อมหรือยัง?",
  ui_story_5040_50400301_75_dialog_content = "พวกคุณกำลังจะเดินทางไกล ตรวจสอบให้แน่ใจว่าคุณมีทุกสิ่งที่คุณต้องการ",
  ui_story_5040_50400301_76_dialog_content = "ใช่! เรามีปลาเฮอริ่ง เนื้อกวาง และเนื้อปลาฉลามกระป๋องมากพอที่จะอยู่ได้อย่างน้อยหนึ่งเดือน",
  ui_story_5040_50400301_77_dialog_content = "ของแห้ง มีตราประทับแช่แข็งกุ้งและปลาเพียงพอสำหรับ 2 เดือน",
  ui_story_5040_50400301_78_dialog_content = "จากนั้นในกรณีฉุกเฉิน มีเตาพกพา ค้อน 10 ปอนด์ มีด พลั่ว กาต้มน้ำ รองเท้าบูท เสื้อกันฝน...",
  ui_story_5040_50400301_79_dialog_content = "รอสักครู่. คุณกำลังจะไปลูโมโปลิสใช่ไหม? และไม่รอดในถิ่นทุรกันดารของ Secret Territory?",
  ui_story_5040_50400301_80_dialog_content = "แน่นอนว่ามันเกินจริงไปหน่อยเหรอ? คุณคิดว่าลูโมโพลิสเป็นสถานที่แบบไหน?",
  ui_story_5040_50400301_81_dialog_content = "เรากำลังเยี่ยมชม Lumopolis, Gannon City และ Rediesel Desert ในทริปนี้ ฉันต้องการที่จะเตรียมตัวให้พร้อมที่สุด",
  ui_story_5040_50400301_82_dialog_content = "นั่นเป็นความคิดที่ถูกต้อง แต่ลองนึกถึงสิ่งที่คุณจะใช้จริง ไม่ใช่ว่าคุณจะอดอยากในที่ที่คุณกำลังจะไป",
  ui_story_5040_50400301_83_dialog_content = "...",
  ui_story_5040_50400301_84_dialog_content = "อะไร กำลังเดินทาง? กับคนแปลกหน้า?!",
  ui_story_5040_50400301_85_dialog_content = "ใจเย็นๆ ธารา มันเป็นการเดินทาง แต่เราหวังเป็นอย่างยิ่งว่ามันจะช่วยให้คุณฟื้นความทรงจำได้",
  ui_story_5040_50400301_86_dialog_content = "แน่นอนคุณต้องการที่จะจำ?",
  ui_story_5040_50400301_87_dialog_content = "แน่นอนฉันรู้ แต่นี่มันบ้าไปแล้ว",
  ui_story_5040_50400301_88_dialog_content = "ยังไงก็ตาม ฉันลืมแต่เรื่องที่เกี่ยวข้องกับคุณ",
  ui_story_5040_50400301_89_dialog_content = "คุณพูดอย่างนั้น แต่ความทรงจำของเราร่วมกันมีความสำคัญต่อทั้งคุณและฉัน",
  ui_story_5040_50400301_90_dialog_content = "อืออ...",
  ui_story_5040_50400301_91_dialog_content = "ฉันเคารพความคิดเห็นของคุณ แน่นอนฉันรู้ แต่อย่างน้อยฉันก็อยากจะลองเอาความทรงจำของคุณกลับคืนมาด้วยการเดินทาง",
  ui_story_5040_50400301_92_dialog_content = "คุณคิดอย่างไร? ฉันจะไม่บังคับให้คุณไปถ้าคุณไม่ต้องการจริงๆ",
  ui_story_5040_50400301_93_dialog_content = "(โอ้ ไม่อยากจะเชื่อเลยว่าเราจะทำสิ่งนี้ ทำไมฉันถึงเป็นคนอ่อนโยน?)",
  ui_story_5040_50400301_94_dialog_content = "สบายใจเถอะธารา ฉันจะดูแลคุณ! ไม่มีอะไรต้องกังวล!",
  ui_story_5040_50400301_95_dialog_content = "งานของคุณในทริปนี้คือสนุก!",
  ui_story_5040_50400301_96_dialog_content = "ฉันไม่รู้ด้วยซ้ำว่าคุณเป็นใคร อย่าคิดว่าคุณทำดีกับฉันได้ แล้วฉันจะหวั่นไหวหรืออะไรทำนองนั้น",
  ui_story_5040_50400301_97_dialog_content = "ฉันอยากกลับบ้าน.",
  ui_story_5040_50400301_98_dialog_content = "ฉันจะพาคุณกลับบ้าน จุดสุดท้ายของเราคือทะเลทราย",
  ui_story_5040_50400301_99_dialog_content = "เราจะสนุกไปพร้อมกัน! และในระหว่างนี้ เราจะคิดวิธีที่จะเขย่าความจำของคุณ",
  ui_story_5040_50400301_100_dialog_content = "ดี. อะไรก็ตาม.",
  ui_story_5040_50400301_101_dialog_content = "ถ้าอย่างนั้นถ้าคุณพร้อมแล้วก็ถึงเวลาไป ฉันจะพาคุณไปที่ลูโมโพลิส เพราะยังไงฉันก็ต้องรายงานกลับไปนาร็อกเซลอยู่ดี",
  ui_story_5040_50400301_102_dialog_content = "PlayerName! รอ!",
  ui_story_5040_50400301_103_dialog_content = "หา?",
  ui_story_5040_50400301_104_dialog_content = "*หอบ* ว้าย ฉันดีใจที่ตามทัน!",
  ui_story_5040_50400301_105_dialog_content = "ถ้าไม่ใช่นกน้อยแห่งแดนเหนือ! น่ารักแม้ยามหมดลมหายใจ",
  ui_story_5040_50400301_106_dialog_content = "โปรดอย่าแกล้งฉัน เลดี้ Jeriah! อืม... ฉันได้ยินมาว่าพวกคุณกำลังจะไปที่ลูโมโพลิส พาพวกเราไปด้วยได้ไหม?",
  ui_story_5040_50400301_107_dialog_content = "\"เรา\"?",
  ui_story_5040_50400301_108_dialog_content = "เธออาจหมายถึงบุคคลแปลก ๆ ที่ดูน่าสงสัยเหมือน Eclipsite หรือไม่?",
  ui_story_5040_50400301_109_dialog_content = "Y-คุณไม่สามารถบอกใครก็ได้ว่าเขาดูเหมือน Eclipsite!",
  ui_story_5040_50400301_110_dialog_content = "นี่คือญาติห่างๆ ของฉัน! เธอชื่อเซเบิล",
  ui_story_5040_50400301_111_dialog_content = "H-สวัสดี... ทุกคน...",
  ui_story_5040_50400301_112_dialog_content = "(ฉันแน่ใจว่า Sable นี้ให้ Darkflow อย่างจริงจัง ... )",
  ui_story_5040_50400301_113_dialog_content = "(แต่ไม่มีสัญญาณเตือนภัยอื่นดังขึ้น ดีที่สุดที่จะรอดู)",
  ui_story_5040_50400301_114_dialog_content = "นกสีดำตัวน้อยเหรอ? ชุดที่น่าสนใจที่คุณมี",
  ui_story_5040_50400301_115_dialog_content = "S-Sable ชอบชุดที่เป็นทางการ! เธอไม่ค่อยออกไปไหน เธอเลยอยากแต่งตัวนิดหน่อย",
  ui_story_5040_50400301_116_dialog_content = "(ด้วยเหตุผลบางอย่างที่อธิบายไม่ได้ ดูเหมือนเธอจะชอบชุดนั้นจริงๆ ชอบมาก มันอาจจะเป็นเครื่องรางแปลกๆ หรือเปล่า?)",
  ui_story_5040_50400301_117_dialog_content = "แล้วพวกนายอยากไปลูโมโพลิสด้วยมั้ย?",
  ui_story_5040_50400301_118_dialog_content = "ฉันอยากพาเธอไปดูในช่วงเทศกาล คุณช่วยพาเราไปด้วยได้ไหม ฉันบังเอิญมีจดหมายที่ต้องส่งไปให้ลูโมโพลิสด้วย",
  ui_story_5040_50400301_119_dialog_content = "แน่นอน! ถ้าพร้อมแล้วเราไปกันเลย",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>โซรอซ</color>",
  ui_story_5040_50400301_121_dialog_content = "คุณจะไม่พักผ่อนบ้างเหรอ Jeriah?",
  ui_story_5040_50400301_122_dialog_content = "อิอิ... การอ่านหนังสือคือการพักผ่อนสำหรับฉัน",
  ui_story_5040_50400301_123_dialog_content = "และฉันไม่เหนื่อย",
  ui_story_5040_50400301_124_dialog_content = "ไปนอนซะถ้าเหนื่อยแล้ว คาเลสไทต์ตัวน้อย",
  ui_story_5040_50400301_125_dialog_content = "ว้าว ที่น่าประทับใจ ฉันไม่เข้าใจสิ่งที่คุณกำลังอ่าน",
  ui_story_5040_50400301_126_dialog_content = "เราแต่ละคนมีความสนใจของเรา ฉันชอบอ่านตำราโบราณ",
  ui_story_5040_50400301_127_dialog_content = "มันผ่อนคลายกว่าการจัดการกับพวกออโรเรียนมาก",
  ui_story_5040_50400301_128_dialog_content = "หา?",
  ui_story_5040_50400301_129_dialog_content = "อีกอย่าง เมื่อเราไปถึงลูโมโพลิส คุณจะไปหานาร็อกเซลไหม",
  ui_story_5040_50400301_130_dialog_content = "เรายังมีสิ่งที่ต้องทำ ฉันจะไปคุยกับเธอก่อนเมื่อเราไปถึงที่นั่น",
  ui_story_5040_50400301_131_dialog_content = "อ๊ากกก!!",
  ui_story_5040_50400301_132_dialog_content = "?!",
  ui_story_5040_50400301_133_dialog_content = "สุริยุปราคา! ท่านหญิงเยริอาห์ PlayerName, ระวัง!",
  ui_story_5040_50400301_134_dialog_content = "ช่วยด้วย...นะ...!",
  ui_story_5040_50400301_135_dialog_content = "Eclipsites เข้ามาได้อย่างไร? พวกเขาติดตามใครบางคนเข้ามาหรือไม่?",
  ui_story_5040_50400301_136_dialog_content = "เราสามารถพูดคุยเกี่ยวกับเรื่องนี้ในภายหลัง มาจัดการกับสิ่งที่ไม่น่าดูเหล่านั้นก่อน",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>หลังจากจัดการกับ Eclipsites แล้ว ทุกคนก็พักผ่อน พวกเขามาถึงอย่างปลอดภัยและสบายดีในลูโมโปลิส...</color>",
  ui_story_5040_50400302_2_dialog_content = "ว้า นั่นเป็นการตรวจสอบของศุลกากรที่เข้มงวด แต่โชคดีที่พวกเขาไม่ได้ทำให้อะไรยากเกินไป",
  ui_story_5040_50400302_3_dialog_content = "(หาก Caelestite ไม่รับรองเรา ผ้าคลุมของ Sable คงจะปลิวไปแล้ว ขอบคุณพระเจ้าที่เราสามารถติดตามเพื่อเข้าไปในเมืองได้)",
  ui_story_5040_50400302_4_dialog_content = "PlayerName! ท่านหญิงเยริอาห์! ฉันจะพาญาติของฉันไปรอบๆ เมือง และส่งจดหมายไปให้ในขณะที่ฉันอยู่ที่นี่! แล้วพบกันใหม่!",
  ui_story_5040_50400302_5_dialog_content = "เธอเพิ่งออกไป!",
  ui_story_5040_50400302_6_dialog_content = "...",
  ui_story_5040_50400302_7_dialog_content = "ว้าว... นี่คือลูโมโพลิส! มันมีกลิ่นอายที่แตกต่างออกไปอย่างแน่นอน",
  ui_story_5040_50400302_8_dialog_content = "คุณคิดอย่างไรธารา?",
  ui_story_5040_50400302_9_dialog_content = "...นี่ไม่ใช่ครั้งแรกของฉันที่นี่",
  ui_story_5040_50400302_10_dialog_content = "ด-ได้...",
  ui_story_5040_50400302_11_dialog_content = "อย่าเสียเวลากันเลย เราควรไปหานาร็อกเซล",
  ui_story_5040_50400302_12_dialog_content = "นาร็อกเซล! เป็นตลอดไป!",
  ui_story_5040_50400302_13_dialog_content = "เดี๋ยวก่อน ใคร... อิเหนา?!",
  ui_story_5040_50400302_14_dialog_content = "เป็นเวลานานแล้ว! อะไรนำคุณไปสู่ Lumopolis? พ่อแม่ของคุณกับคุณโนวิโอสบายดีไหม",
  ui_story_5040_50400302_15_dialog_content = "ทุกคนทำได้ดีมาก",
  ui_story_5040_50400302_16_dialog_content = "และนี่คือข้อความที่ฉันพูดถึงเสมอในจดหมายของฉัน ธารา",
  ui_story_5040_50400302_17_dialog_content = "...",
  ui_story_5040_50400302_18_dialog_content = "อันที่จริง นาร็อกเซล เรากลับมาที่ลูโมโปลิสแล้ว เพราะเรามีเรื่องเล็กน้อย...",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>หลังจากเล่าเรื่องให้นาร็อกเซลฟัง...</color>",
  ui_story_5040_50400302_20_dialog_content = "เป็นไปได้ยังไง",
