  ui_story_5040_50400401_53_dialog_content = "(จบแล้ว... ดูเหมือนว่าเขาจะสูญเสียพลังงานทั้งหมดไปแล้ว)",
  ui_story_5040_50400401_54_dialog_content = "เฮ้อ... ฉันไม่รู้จะทำยังไงแล้ว",
  ui_story_5040_50400401_55_dialog_content = "ฉันทำอะไรไม่ถูก... ถ้าเพียงแต่เธอจะบอกใบ้ให้ฉัน! แล้วจะได้รู้ว่าต้องทำยังไง...",
  ui_story_5040_50400401_56_dialog_content = "เอ่อ...",
  ui_story_5040_50400401_57_dialog_content = "เราเคยคุยกันทุกเรื่อง โดยเฉพาะเรื่องที่เราไม่เข้าใจเกี่ยวกับโลกของเรา แต่เดี๋ยวนี้...เรื่องมันลงเอยแบบนี้ได้ยังไง?",
  ui_story_5040_50400401_58_dialog_content = "PlayerNameคุณเป็นชาวคาเลสไทต์ คุณต้องให้สาวๆ เข้าแถวหน้าประตูบ้านคุณ คุณเข้าใจสิ่งที่ฉันกำลังจะผ่าน?",
  ui_story_5040_50400401_59_dialog_content = "U-Uh นั่นเป็นการพูดเกินจริงเล็กน้อย",
  ui_story_5040_50400401_60_dialog_content = "แต่ฉันคิดว่าตราบใดที่ความรู้สึกที่คนสองคนมีให้กันแข็งแรงพอ พวกเขาก็สามารถเอาชนะความยากลำบากได้",
  ui_story_5040_50400401_61_dialog_content = "ฉันและเพื่อนที่ดีสองคน เราผ่านอะไรมาด้วยกันมากมาย เราเคยช่วยชีวิตกันและกันจากประตูแห่งความตายมาแล้วสองสามครั้ง!",
  ui_story_5040_50400401_62_dialog_content = "แต่ประสบการณ์ทั้งหมดเหล่านั้นทำให้เราเชื่อใจกันมากขึ้น เราเต็มใจทำทุกอย่างเพื่อกันและกัน แม้ว่านั่นหมายถึงการทำร้ายตัวเองก็ตาม",
  ui_story_5040_50400401_63_dialog_content = "ฉันมั่นใจว่าคุณกับธาราเหมือนกัน",
  ui_story_5040_50400401_64_dialog_content = "O-แน่นอน ฉันจะทำทุกอย่างเพื่อเธอ! ฉันยอมเสี่ยงชีวิตด้วยซ้ำถ้าต้อง!",
  ui_story_5040_50400401_65_dialog_content = "ก็แค่ว่าบางครั้งฉันก็ไม่กล้าตัดสินใจ... ฉันไม่สามารถตัดสินใจเพียงเสี้ยววินาทีเหมือนคนอื่นๆ ได้ นั่นอาจเป็นเหตุผลที่เธอคิดว่าฉันขาดความเป็นผู้ชาย...",
  ui_story_5040_50400401_66_dialog_content = "อย่าพูดอย่างนั้นอิเหนา! ใครบอกว่าผู้ชายจะต้องไม่ทางใดก็ทางหนึ่ง? เราทุกคนแตกต่างกันและไม่เป็นไร",
  ui_story_5040_50400401_67_dialog_content = "ไม่มีใครสมบูรณ์แบบ แต่ถ้าคุณสองคนยังอยู่ด้วยกัน... นั่นหมายความว่ามีบางอย่างในตัวคุณที่เธอพบว่ามีเสน่ห์พอที่จะอยู่เคียงข้าง!",
  ui_story_5040_50400401_68_dialog_content = "*สะอื้น* ฉัน... ฉันแค่หวังว่าเธอจะรู้สึกอย่างนั้นจริงๆ!!",
  ui_story_5040_50400401_69_dialog_content = "อยู่นั่น อย่าร้องไห้...",
  ui_story_5040_50400401_70_dialog_content = "อุ๊ย!",
  ui_story_5040_50400401_71_dialog_content = "เรากำลังขัดขวางช่วงเวลาที่สวยงามและมีชีวิตชีวาอยู่หรือเปล่า?",
  ui_story_5040_50400401_72_dialog_content = "Gin ฉันรู้สึกมีแรงบันดาลใจมาก!",
  ui_story_5040_50400401_73_dialog_content = "ถูกผูกมัดด้วยความคาดหวังของสังคม คู่รักสองคนที่ไม่สามารถเห็นหน้ากัน—",
  ui_story_5040_50400401_74_dialog_content = "เห็นได้ชัดว่าพวกเขากอดกันกลางวันแสกๆ",
  ui_story_5040_50400401_75_dialog_content = "แม้ว่าจะเป็นวัน Mooncrown แต่คู่รักทั้งสองก็ไม่มีทางเลือกอื่นนอกจากพบกันในมุมที่เงียบสงบของ Umbraton ห่างไกลจากสายตาที่สอดรู้สอดเห็น—",
  ui_story_5040_50400401_76_dialog_content = "มีคนอยู่ทุกที่...",
  ui_story_5040_50400401_77_dialog_content = "นี่ไม่ใช่สิ่งที่สวยงามที่สุดที่คุณเคยเห็นใช่ไหม จิน? ฉันต้องการทำทุกวิถีทางเพื่อช่วยพวกเขา! และอาจจะหาอะไรเล็กน้อยสำหรับตัวเองในขณะที่ฉันทำอยู่!",
  ui_story_5040_50400401_78_dialog_content = "ฟังดูเป็นความคิดที่ยอดเยี่ยม",
  ui_story_5040_50400401_79_dialog_content = "เอ่อ ฉันคิดว่าคุณเข้าใจผิด—",
  ui_story_5040_50400401_80_dialog_content = "ฉันชื่นชมความกล้าหาญของคุณ คนของฉัน ฉันขอชื่อคุณได้ไหม",
  ui_story_5040_50400401_81_dialog_content = "เอ็ม-มี? ฉันชื่ออิเหนา...",
  ui_story_5040_50400401_82_dialog_content = "คุณมีความยิ่งใหญ่ในตัวคุณ Adonis คนที่ทำให้คุณเหนือกว่าใครๆ โดยเฉพาะผู้ชายที่อยู่ข้างๆ คุณ",
  ui_story_5040_50400401_83_dialog_content = "ทำไมจู่ๆคุณถึงยิงใส่ฉันล่ะ!",
  ui_story_5040_50400401_84_dialog_content = "คุณต้องเป็นประเภทที่ยอมทำทุกอย่างเพื่อความรัก ฉันสามารถบอกได้เพียงแค่มองไปที่คุณ",
  ui_story_5040_50400401_85_dialog_content = "อมยิ้มของฉันก็รู้สึกแบบเดียวกันเช่นกัน",
  ui_story_5040_50400401_86_dialog_content = "แต่ขอยุติการพูดคุยเล็ก ๆ ที่ไม่จำเป็น สำหรับวันไหว้พระจันทร์ปีนี้ เรามีภาพวาดที่หายากมากมาขาย ซึ่งผมเชื่อว่าเหมาะกับคุณที่สุด",
  ui_story_5040_50400401_87_dialog_content = "เป็นเรื่องราวโศกนาฏกรรมของความรักต้องห้ามระหว่างสองคู่รักข้ามดวงดาว...",
  ui_story_5040_50400401_88_dialog_content = "ภาพวาดที่สวยงามและหายากนี้สามารถเป็นของคุณได้ในราคาที่สมเหตุสมผล แต่เฉพาะวันนี้เท่านั้น!",
