  ui_story_5040_50400401_102_dialog_content = "<size=45>กรร!</size>",
  ui_story_5040_50400401_103_dialog_content = "การเข้ามายุ่งเกี่ยวกับธุรกิจของฉันช่างน่าหงุดหงิด",
