  ui_story_5040_50400402_10_dialog_content = "หา?",
  ui_story_5040_50400402_11_dialog_content = "คุณกำลังพูดถึงอิเหนา? เขาอยู่กับ Tara และ Jeriah จาก Courier Union ก่อนหน้านี้",
