  ui_story_5040_50400402_13_dialog_content = "แล้วคุณคือ...?",
  ui_story_5040_50400402_14_dialog_content = "ทักทาย! ฉันชื่อทีน่า เป็นผู้พิพากษาจาก Lumo Hall of Justice ขอโทษที่ลืมแนะนำตัวก่อนนะครับ",
