  ui_story_5040_50400402_17_dialog_content = "ขอบคุณคนส่งของคนนั้น ฉันเจอสิ่งที่ตามหาที่นี่ใน Umbraton",
  ui_story_5040_50400402_18_dialog_content = "จริงหรือ ทั้งหมดนี้ต้องขอบคุณ Jeriah... ฉันดีใจที่เธอช่วยได้ เพราะคิดว่าฉันคงทำอะไรไม่ได้",
  ui_story_5040_50400402_19_dialog_content = "ไม่ว่าในกรณีใด ฉันแน่ใจว่าเพื่อนของคุณและคนรักของเขามีความสุขที่คุณสามารถหาแสตมป์จากปีที่แล้วได้",
  ui_story_5040_50400402_20_dialog_content = "คุณพูดถูกอย่างแน่นอน เขาแทบจะกระโดดด้วยความดีใจเมื่อฉันให้มัน",
  ui_story_5040_50400402_21_dialog_content = "เขาขอบคุณฉันซ้ำแล้วซ้ำเล่าก่อนจะวิ่งกลับบ้านให้เร็วที่สุดเท่าที่จะทำได้เพื่อเขียนจดหมายรัก",
  ui_story_5040_50400402_22_dialog_content = "พ่อค้าที่ฉันได้รับมาจากมีรายการที่น่าสนใจมากมาย ฉันกำลังเดินทางไปดูสินค้าของเธอเพิ่มเติม เมื่อบังเอิญเจอคุณสองคน",
  ui_story_5040_50400402_23_dialog_content = "... สบายดีไหมครับท่าน? คุณดูซีดๆ หน่อย... มีอะไรเกิดขึ้นหรือเปล่า?",
  ui_story_5040_50400402_24_dialog_content = "ที่จริงฉัน...",
  ui_story_5040_50400402_25_dialog_content = "อา... ฉันเห็นแล้ว! ไม่น่าแปลกใจเลยที่ฉันรู้สึกราวกับว่ามีบางอย่างแปลก ๆ ระหว่างคุณสองคน!",
  ui_story_5040_50400402_26_dialog_content = "คุณจะไปที่ Illumina ใช่ไหม ในกรณีนี้ ฉันสามารถถามคนรักของเพื่อนของฉันได้ว่าเธอรู้วิธีรักษาหรือไม่?",
  ui_story_5040_50400402_27_dialog_content = "ฮ-ฮะ?",
  ui_story_5040_50400402_28_dialog_content = "ฉันจะตรงไปตรงมากับคุณ เธอทำงานให้กับ Black Umbrella Laboratories ใน Gannon City",
  ui_story_5040_50400402_29_dialog_content = "หากมีวิธีการรักษา ความรู้ของเธออาจเป็นประโยชน์กับคุณ! แค่เอ่ยชื่อของฉันกับเธอ แล้วเธอจะช่วยเท่าที่เธอทำได้",
