  ui_story_5040_50400402_47_dialog_content = "คุณจำอะไรได้บ้าง",
  ui_story_5040_50400402_48_dialog_content = "ลูโมโปลิส...เดินทางไกล...",
  ui_story_5040_50400402_49_dialog_content = "ฉันมาที่นี่...เพื่อพบใครบางคน...",
  ui_story_5040_50400402_50_dialog_content = "แต่ใคร...? ฉันสัญญาว่าจะไปเจอใคร...ในลุมโปลิส...?",
