  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>วันต่อมา...</color>",
  ui_story_5040_50400402_62_dialog_content = "เอาล่ะ ทุกคนพร้อมหรือยัง? อย่าลืมทุกสิ่งที่คุณต้องการ!",
  ui_story_5040_50400402_63_dialog_content = "ฮิฮิ... ไม่ได้ไป Illumina นานแล้ว ฉันสงสัยว่านกน้อยเหล่านั้นกำลังทำอะไรอยู่?",
  ui_story_5040_50400402_64_dialog_content = "โปรดอย่าสร้างปัญหาให้พวกเขามากกว่านี้ Jeriah",
  ui_story_5040_50400402_65_dialog_content = "สหพันธ์อิลลูมิน่าควรจะเป็นประเทศที่มีกำลังทหารสูงใช่ไหม? Tara บอกฉันเกี่ยวกับเรื่องนี้ก่อนหน้านี้ ... ฉันอยากจะเห็นด้วยตัวเองเสมอ!",
