  ui_story_5040_50400502_91_dialog_content = "ง-อย่าพูดแบบนั้นสิ! การผจญภัยเล็ก ๆ น้อย ๆ ของเราทำให้เราใกล้ชิดกันมากขึ้น คุณว่าไหม?",
  ui_story_5040_50400502_92_dialog_content = "ซ-พูดว่าใคร?!",
  ui_story_5040_50400502_93_dialog_content = "ตอนนี้เรามี Feather Seal ของ Illumina แล้ว เราจะไปที่ไหนกันต่อดี?",
  ui_story_5040_50400502_94_dialog_content = "เราไม่ได้มาที่ Gannon City ทุกวัน ไปลองชิมอาหารท้องถิ่นและดูหนังกันเถอะ!",
  ui_story_5040_50400502_95_dialog_content = "นั่นน่าจะทำให้พวกเราทุกคนมีจิตวิญญาณแห่งวันหยุด!",
  ui_story_5040_50400502_96_dialog_content = "เราสามารถกินอาหารของ Illumina ได้ทุกเมื่อที่เราต้องการ",
  ui_story_5040_50400502_97_dialog_content = "ขณะที่ส่งจดหมาย ฉันได้ยินว่ามีการขนส่งปืนไรเฟิลพลังงานจลน์เพิ่งมาจาก Undercity ฉันอยากไปดูพวกเขาถอดอาวุธออก",
  ui_story_5040_50400502_98_dialog_content = "คุณต้องการไปดูปืนในวัน Mooncrown หรือไม่? ไม่ค่อยโรแมนติกเท่าไหร่...",
  ui_story_5040_50400502_99_dialog_content = "ถ้าเธอไม่อยากไป ฉันไปเองได้เสมอ",
  ui_story_5040_50400502_100_dialog_content = "ฉัน...",
  ui_story_5040_50400502_101_dialog_content = "ใจเย็นๆ นะคุณสองคน ยังมีเรื่องสำคัญที่ต้องจัดการอีกมาก",
  ui_story_5040_50400502_102_dialog_content = "หรือเธอทั้งสองลืมเหตุผลที่เรามาที่นี่ตั้งแต่แรก?",
  ui_story_5040_50400502_103_dialog_content = "โอ้ใช่! เรายังต้องไปถามผู้หญิงคนนั้นใน Black Umbrella Laboratories เกี่ยวกับความจำเสื่อมของ Tara!",
  ui_story_5040_50400502_104_dialog_content = "O-โอ้ ใช่...",
  ui_story_5040_50400502_105_dialog_content = "...",
  ui_story_5040_50400502_106_dialog_content = "มาทำให้เสร็จก่อนที่มันจะมืด มาเร็ว.",
  ui_story_5040_50400601_1_dialog_content = "(นานเกินไปแล้วจริงๆ)",
  ui_story_5040_50400601_2_dialog_content = "... และนั่นคือเหตุผลที่เรามาที่นี่ในวันนี้ ขออภัยสำหรับปัญหาทั้งหมด",
  ui_story_5040_50400601_3_dialog_content = "ไม่มีปัญหาเลย! ท้ายที่สุด ฉันเป็นหนี้คุณทีน่าและพวกคุณทุกคนมาก!",
  ui_story_5040_50400601_4_dialog_content = "ลูโมโพลิสและอิลลูมินามีความแตกต่างอยู่เสมอ ซึ่งทำให้เราสองคนลำบากมาก",
  ui_story_5040_50400601_5_dialog_content = "แต่เรามีความสุขที่มีกลุ่มคนอย่าง Miss Tina ที่สนับสนุนเรา!",
  ui_story_5040_50400601_6_dialog_content = "แม้จะเป็นชนชั้นสูง แต่เธอก็สนับสนุนความรักของเราเสมอมา",
  ui_story_5040_50400601_7_dialog_content = "จากที่ฉันเข้าใจ ร่างกายของเธอต้องการการนอนที่เพียงพอเพื่อที่จะทำงานได้อย่างถูกต้อง แม้ว่าเธอจะอยู่ในสภาพนี้ เธอก็ยังพยายามหาตราประทับนั้นมาให้เรา",
  ui_story_5040_50400601_8_dialog_content = "ใช่ ไม่มีการปฏิเสธว่าเธอเป็นคนที่เหลือเชื่อ",
  ui_story_5040_50400601_9_dialog_content = "เธอใจดีและสุภาพเสมอ",
  ui_story_5040_50400601_10_dialog_content = "แต่ฉันรู้ว่าเธอมีปัญหามากพอที่จะจัดการ ฉันได้ยินมาว่างานของเธอใน Hall of Justice นั้น... น่าสนใจ พูดน้อย",
  ui_story_5040_50400601_11_dialog_content = "ฉันไม่รู้ว่าเราจะมีโอกาสได้เจอกันอีกเมื่อไหร่ ฉันหวังว่าฉันจะรู้เพิ่มเติมเกี่ยวกับเธอ",
  ui_story_5040_50400601_12_dialog_content = "แต่จากที่เธอพูด ดูเหมือนว่าคุณและคนรักของคุณจะมีเรื่องหนักใจพอกัน",
  ui_story_5040_50400601_13_dialog_content = "ใช่. ทำไมคุณสองคนไม่หนีออกไป",
  ui_story_5040_50400601_14_dialog_content = "เพราะเราต่างก็มีสิ่งที่ต้องทำ เราอาจเป็นคู่รักกัน แต่ความรับผิดชอบของเราจะมาก่อนเสมอ",
  ui_story_5040_50400601_15_dialog_content = "เขาและฉันต่างมีสำนึกในหน้าที่อันแข็งแกร่ง ซึ่งนั่นอาจเป็นเหตุผลว่าทำไมเราถึงถูกดึงดูดเข้าหากันในตอนแรก",
  ui_story_5040_50400601_16_dialog_content = "ถ้าคนสองคนจริงใจต่อตนเองและกันและกัน เรื่องอย่างเช่นระยะทางจะกลายเป็นเรื่องเล็กน้อย ท้ายที่สุดแล้วหัวใจของเราก็อยู่ด้วยกันเสมอ",
  ui_story_5040_50400601_17_dialog_content = "ใจคุณ...ยังอยู่ด้วยกันเสมอ?",
  ui_story_5040_50400601_18_dialog_content = "ฉันรู้สึกแบบเดียวกันด้วย ไม่มีปัญหาใดยากเกินเอาชนะ ตราบใดที่คุณยังรักกัน!",
  ui_story_5040_50400601_19_dialog_content = "ฮ่าฮ่าฮ่า! ตอนนี้เราควรกลับไปทำธุรกิจกันจริงๆ คุณชื่อ ธาราใช่ไหม? ฉันคิดว่าฉันเข้าใจภาวะที่กลืนไม่เข้าคายไม่ออกของคุณไม่มากก็น้อย",
  ui_story_5040_50400601_20_dialog_content = "ขออภัย ตอนนี้ฉันเป็นเพียงนักศึกษาฝึกงาน แต่ให้ฉันถามเพื่อนร่วมงานและดูว่าพวกเขาคิดอย่างไร กรุณารอซักครู่.",
  ui_story_5040_50400601_21_dialog_content = "ขอบคุณอีกครั้ง!",
  ui_story_5040_50400601_22_dialog_content = "<size=33>Jeriah... คุณไม่คิดว่าพวกเขาจะหาว่าฉันแกล้งทำใช่ไหม?</size>",
  ui_story_5040_50400601_23_dialog_content = "จะดีกว่าไหมถ้ามาทำความสะอาดตรงจุดนี้?",
  ui_story_5040_50400601_24_dialog_content = "<size=33>ไม่มีทาง! ฉันไม่สามารถแสดงใบหน้าของฉันให้คนอื่นเห็นถ้าฉันทำ!</size>",
  ui_story_5040_50400601_25_dialog_content = "คุณไม่ได้คิดอย่างนั้นเมื่อคุณเกิดความคิดบ้าๆ นี้ขึ้นมา?",
  ui_story_5040_50400601_26_dialog_content = "<size=33>อย่างไรก็ตาม ถ้าความลับรั่วไหล ฉันต้องการให้คุณช่วยดับไฟจริงๆ</size>",
  ui_story_5040_50400601_27_dialog_content = "...",
  ui_story_5040_50400601_28_dialog_content = "(ฉันรู้ว่าเธอแกล้งทำเป็นตลอดเวลา ... ฉันเดาว่าฉันจะแสร้งทำเป็นไม่รู้อะไรเลย)",
  ui_story_5040_50400601_29_dialog_content = "คุณสองคนกำลังพูดถึงอะไร",
  ui_story_5040_50400601_30_dialog_content = "ไม่มีอะไร! เราแค่บอกว่าห้องทดลองนี้ดูน่าทึ่งมาก!",
  ui_story_5040_50400601_31_dialog_content = "ก็ใช่... มีการ์ดดูแลที่นี่ และเธออยู่ในระดับที่แตกต่างไปจากเดิมอย่างสิ้นเชิง",
  ui_story_5040_50400601_32_dialog_content = "ธารา? ทำไมคุณถึงสั่น?",
  ui_story_5040_50400601_33_dialog_content = "โอ้ เธอแค่หนาวนิดหน่อย!",
  ui_story_5040_50400601_34_dialog_content = "จริงหรือ ที่นี่ไม่รู้สึกหนาวเลยสักนิด...",
  ui_story_5040_50400601_35_dialog_content = "ขอโทษที่ทำให้รอ! ถ้าทุกคนจะตามฉันมา ฉันอยากจะแนะนำคุณให้รู้จักกับหนึ่งในนักวิจัยอาวุโสของที่นี่",
  ui_story_5040_50400601_36_dialog_content = "ช่วยนำทางให้ฉันที!",
  ui_story_5040_50400601_37_dialog_content = "โจล่า? นี่คือธารา หญิงสาวที่ฉันพูดถึงก่อนหน้านี้ ดูเหมือนว่าเธอกำลังทุกข์ทรมานจากกรณีความจำเสื่อม",
  ui_story_5040_50400601_38_dialog_content = "เราขอขอบคุณสำหรับความช่วยเหลือใด ๆ ที่คุณสามารถให้เราได้!",
  ui_story_5040_50400601_39_dialog_content = "ฉันยินดีให้ยืมมือมากกว่า! อย่างน้อยที่สุดที่ฉันทำได้ หลังจากที่คุณทำเพื่อเพื่อนร่วมงานของฉันที่นี่",
  ui_story_5040_50400601_40_dialog_content = "ถ้าอย่างนั้น คุณธารา... คุณจะว่าอะไรไหมถ้าฉันจะตรวจสอบคุณอย่างใกล้ชิด?",
  ui_story_5040_50400601_41_dialog_content = "G-ไปเถอะ...",
  ui_story_5040_50400601_42_dialog_content = "น่าเสียดายที่วันนี้มิการ์ดไม่ได้อยู่ที่นี่ ฉันไม่ใช่ผู้เชี่ยวชาญในเรื่องเหล่านี้ แต่ฉันจะพยายามทำให้ดีที่สุด",
  ui_story_5040_50400601_43_dialog_content = "(ขอบคุณพระเจ้า!)",
  ui_story_5040_50400601_44_dialog_content = "อืม... มองแวบแรกก็ไม่มีอะไรผิดปกติ เราจะต้องทำการทดสอบหลายอย่างเพื่อยืนยันสภาพร่างกายของคุณ",
  ui_story_5040_50400601_45_dialog_content = "ว-แบบทดสอบอะไร...?",
  ui_story_5040_50400601_46_dialog_content = "(รอยยิ้มของเขาดูน่ากลัว...)",
  ui_story_5040_50400601_47_dialog_content = "ไม่ต้องกังวล! หยิกเล็กน้อยที่นี่ ดึงเล็ก ๆ น้อย ๆ แล้วมันจะจบลงก่อนที่คุณจะรู้ตัว!",
  ui_story_5040_50400601_48_dialog_content = "กรรรร!",
  ui_story_5040_50400601_49_dialog_content = "อ๊ะ ไม่นะ...",
  ui_story_5040_50400602_1_dialog_content = "เฮ้! คุณไม่ได้พูดอะไรเกี่ยวกับการใช้ Eclipsites เพื่อเรียกใช้การทดสอบของคุณ!",
  ui_story_5040_50400602_2_dialog_content = "เตือนสักนิดก็ยังดีรู้ยัง!!",
  ui_story_5040_50400602_3_dialog_content = "ฉันขอโทษทุกคน ฉันไม่คิดว่าคุณจะต่อต้านวิธีการของฉันจริงๆ!",
  ui_story_5040_50400602_4_dialog_content = "ท้ายที่สุด พวกคุณค่อนข้างเป็นกลุ่มที่แปลกประหลาด ชาวนอร์ธแลนเดอร์ ชาวทะเลทราย คนส่งของกึ่งมนุษย์... และแน่นอน คาเลสไทต์กลุ่มสุดท้ายในโลก",
  ui_story_5040_50400602_5_dialog_content = "นั่นไม่เกี่ยวข้องเลย เรามาที่นี่เพื่อช่วยให้ Tara ดีขึ้น!",
  ui_story_5040_50400602_6_dialog_content = "แล้วฉันเป็นอะไรกันแน่?",
  ui_story_5040_50400602_7_dialog_content = "จากที่ข้าเห็น ท่านดูมีสุขภาพร่างกายสมบูรณ์ดี",
  ui_story_5040_50400602_8_dialog_content = "... นั่นสินะ? แล้วเราจะทำอะไรได้อีก?",
  ui_story_5040_50400602_9_dialog_content = "คุณสามารถบอกอะไรได้อีกเกี่ยวกับความเจ็บป่วยของเธอ? คุณรู้หรือไม่ว่าเกิดจากอะไร?",
  ui_story_5040_50400602_10_dialog_content = "ขอดูหน่อย... ทุกอย่างเริ่มต้นจากยาวิเศษนั่น นักจิตวิทยาที่ขายให้ฉันบอกว่ามันทำขึ้นโดยใช้ส่วนผสมที่พิเศษมาก",
  ui_story_5040_50400602_11_dialog_content = "บางอย่างเกี่ยวกับหนอนทรายสีชมพูขนาดยักษ์ในทะเลทราย Rediesel... ฉันเดาว่ามันน่าจะเป็นสิ่งมีชีวิตที่หายากมาก?",
  ui_story_5040_50400602_12_dialog_content = "ว่าไหม... หนอนทรายสีชมพู?",
  ui_story_5040_50400602_13_dialog_content = "ย-ใช่?",
  ui_story_5040_50400602_14_dialog_content = "Jola คุณรู้อะไรเกี่ยวกับเรื่องนี้บ้าง",
  ui_story_5040_50400602_15_dialog_content = "...",
  ui_story_5040_50400602_16_dialog_content = "ไม่น่าเชื่อว่าหนอนทรายสีชมพูในตำนานจะกลับมาปรากฏตัวอีกครั้ง...",
  ui_story_5040_50400602_17_dialog_content = "<size=33>อะไร?! เป็นไปไม่ได้!</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>ธารา?</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>ฉันได้จับเกล็ดหนอนทรายสีชมพูเมื่อนานมาแล้ว! พลังจิตบางคนจับมันได้อย่างไร!</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>ถ้าหนอนทรายสีชมพูนี้มีอยู่จริง จะแปลกใจไหมที่รู้ว่ามีคนอื่นมีเกล็ดของมัน?</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>เพราะเท่าที่ฉันรู้ เกล็ดทรายสีชมพูเพียงอันเดียวที่มีจำหน่ายในตลาดทั้งหมด! ทันใดนั้นจะมีอีกอันหนึ่งได้อย่างไร</size>",
  ui_story_5040_50400602_22_dialog_content = "ความเชี่ยวชาญของฉันอยู่ในสาขาพฤกษศาสตร์ ขณะที่ฉันกำลังค้นหาสปอร์ชนิดหนึ่ง วันหนึ่ง Migard พูดถึงหนอนทรายสีชมพูกับฉัน",
  ui_story_5040_50400602_23_dialog_content = "สปอร์นี้ส่วนใหญ่ไม่ได้ถูกวิจัยในช่วงหลายปีที่ผ่านมา และมีการกล่าวถึงในหนังสือเท่านั้น สาเหตุที่เป็นเช่นนี้เพราะมันเติบโตบนเกล็ดของหนอนทรายสีชมพูที่หายากมากเท่านั้น",
  ui_story_5040_50400602_24_dialog_content = "Migard กล่าวว่ามีรายงานของผู้เห็นเหตุการณ์เกี่ยวกับสัตว์ชนิดนี้ แต่มีเพียงไม่กี่รายเท่านั้นที่สามารถพิสูจน์คำกล่าวอ้างของพวกมันได้",
  ui_story_5040_50400602_25_dialog_content = "มันดุร้ายกว่าหนอนทรายทั่วไป ทำให้ยากที่ใครจะเข้าใกล้มัน เกล็ดของมันเป็นส่วนผสมที่หายากและมีค่ามาก ในความเป็นจริง ฉันคิดว่ามีเพียงเครื่องชั่งเดียวที่มีอยู่ในตลาดทั้งหมด",
  ui_story_5040_50400602_26_dialog_content = "ถ้าเจ้านำเกล็ดเหล่านี้มาให้ข้า ข้าอาจจะลองสร้างวิธีรักษาดูก็ได้",
  ui_story_5040_50400602_27_dialog_content = "นอกเหนือจากนั้น ฉันเกรงว่าฉันไม่มีทางออกอื่นให้คุณ",
  ui_story_5040_50400602_28_dialog_content = "...",
  ui_story_5040_50400602_29_dialog_content = "...",
  ui_story_5040_50400602_30_dialog_content = "ดูเหมือนว่าเป้าหมายของเราจะชัดเจนมากสำหรับเรา",
  ui_story_5040_50400602_31_dialog_content = "เยริ?",
  ui_story_5040_50400602_32_dialog_content = "เมื่อพิจารณาว่าจุดหมายต่อไปของเราคือ Rediesel Wrench และฉันเป็นหัวหน้าของ Courier Union ที่นั่น... ถ้าอย่างนั้นฉันจะให้หนอนทรายสีชมพูตัวใดตัวหนึ่งมาชั่งการทดลอง Feather Seal",
  ui_story_5040_50400602_33_dialog_content = "เฮ้ คุณจริงจังไหม",
  ui_story_5040_50400602_34_dialog_content = "ดูเหมือนมีเพียงไม่กี่คนเท่านั้นที่ได้เห็นเจ้าสิ่งนี้... ข้าไม่เคยได้ยินเรื่องนี้มาก่อนแม้จะอยู่ในทะเลทรายมาทั้งชีวิต มีคุณ?",
  ui_story_5040_50400602_35_dialog_content = "ฉันไม่เคยได้ยินเรื่องนี้มาก่อน",
  ui_story_5040_50400602_36_dialog_content = "ถ้าอย่างนั้นทำไมคุณถึงทำการทดลองของเรา!",
  ui_story_5040_50400602_37_dialog_content = "ฉันจะทำมัน! หากมีโอกาสแม้เพียงน้อยนิดที่จะฟื้นความทรงจำของทาร่าได้ ฉันก็ยินดีที่จะลอง",
  ui_story_5040_50400602_38_dialog_content = "หา?",
  ui_story_5040_50400602_39_dialog_content = "อิเหนา! เสียสติไปแล้ว?!",
  ui_story_5040_50400602_40_dialog_content = "พูดตามตรง ฉันไม่มั่นใจเลยสักนิด... เพราะฉันรู้ว่าตัวเองอ่อนแอและขี้อาย—ฉันฆ่าแมลงในบ้านตัวเองไม่ได้ด้วยซ้ำ นับประสาอะไรกับหนอนทรายยักษ์...",
  ui_story_5040_50400602_41_dialog_content = "แต่ทีอาร่ากลับเป็นแบบนี้เพราะฉัน ฉันเลยต้องทำอะไรสักอย่างกับมัน",
  ui_story_5040_50400602_42_dialog_content = "ฉันรู้ว่านิสัยขี้อายของฉันคือสิ่งที่ทำให้เธอผิดหวังตั้งแต่แรก... นั่นคือเหตุผลที่ฉันอยากเปลี่ยนแปลง",
  ui_story_5040_50400602_43_dialog_content = "ฉันไม่สามารถถอยได้ไม่ว่าจะเกิดอะไรขึ้น",
  ui_story_5040_50400602_44_dialog_content = "นั่นเป็นคำพูดที่สะเทือนใจจริงๆ!",
  ui_story_5040_50400602_45_dialog_content = "อิเหนา! ฉัน... ที่จริง ฉัน—",
  ui_story_5040_50400602_46_dialog_content = "คำพูดที่จับใจอิเหนา คุณคิดว่าตอนนี้คุณสามารถกำจัดหนอนทรายนี้ด้วยตัวคนเดียวได้ไหม?",
  ui_story_5040_50400602_47_dialog_content = "ไม่แน่นอน! ฉันต้องการความช่วยเหลือทั้งหมดที่มี ดังนั้นโปรดสอนฉันถึงวิธีการต่อสู้ด้วย!",
  ui_story_5040_50400602_48_dialog_content = "เริ่มฉันด้วย Eclipsites ถ้าคุณต้องทำ! ฉันจะทำทุกอย่างเพื่อให้แข็งแกร่งขึ้น!",
  ui_story_5040_50400602_49_dialog_content = "คุณรู้วิธีการต่อสู้หรือไม่?",
  ui_story_5040_50400602_50_dialog_content = "ฉันจำได้ว่าพ่อของคุณเคยบอกว่าคุณเคยเรียน Luminatics ที่ Novio... ใช่ไหม?",
  ui_story_5040_50400602_51_dialog_content = "ใช่! ตอนเป็นเด็ก ฉันมักจะไปห้องสมุดเสมอ และคุณโนวิโอจะสอนฉันมากมาย",
  ui_story_5040_50400602_52_dialog_content = "Luminatics ของฉันอาจไม่แข็งแรงมากนัก แต่ฉันมีความเข้าใจที่ชัดเจนพอสมควรเกี่ยวกับวิธีการใช้งาน",
  ui_story_5040_50400602_53_dialog_content = "ฮิฮิฮิ... ดี!",
  ui_story_5040_50400602_54_dialog_content = "Jeriah การแสดงออกของคุณทำให้ฉันกลัว",
  ui_story_5040_50400602_55_dialog_content = "ใจเย็นๆ พวกเราทีมเดียวกัน! ไม่ใช่ว่าฉันจะทรมานเขาหรืออะไร",
  ui_story_5040_50400602_56_dialog_content = "สิ่งนี้จะเป็นเรื่องง่าย อย่างที่คุณพูดเอง เราสามารถเริ่มต้นด้วย Eclipsites...",
  ui_story_5040_50400602_57_dialog_content = "ดะ-เดี๋ยวนะ... นายจะให้ฉันสู้กับพวกนั้นจริงๆเหรอ?",
  ui_story_5040_50400602_58_dialog_content = "โอ้สวรรค์ ไม่สิ! มันจะโหดร้ายเกินไปแล้ว! ไม่... ฉันมีความคิดที่ดีกว่านั้น",
  ui_story_5040_50400602_59_dialog_content = "เธอเป็นคู่ต่อสู้ที่เหมาะกับคุณมากกว่า",
  ui_story_5040_50400701_1_dialog_content = "คุณเรียกฉันที่นี่ว่าอะไร เลดี้ Jeriah?",
  ui_story_5040_50400701_2_dialog_content = "Jeriah คุณไม่ได้หมายความว่า...",
  ui_story_5040_50400701_3_dialog_content = "กรา...?",
  ui_story_5040_50400701_4_dialog_content = "ฮิฮิ เย้! เพื่อนตัวน้อยของ Kya เป็นคู่ที่สมบูรณ์แบบสำหรับเขา คุณว่าไหม? ทุกอย่างเกี่ยวกับเธอแทบจะกรีดร้องว่า \"Eclipsite\"",
  ui_story_5040_50400701_5_dialog_content = "ฉันคิดว่าเธอน่าจะเป็นคู่ซ้อมที่ยอดเยี่ยมสำหรับ Adonis!",
  ui_story_5040_50400701_6_dialog_content = "ฉันหมายความว่า ฉันรู้ว่า Sable ดูไม่เหมือนชาว Aurorian คนอื่นๆ เลยสักนิด... แต่คุณไม่คิดว่าการเรียกเธอว่า Eclipsite จะเวอร์เกินไปเหรอ?",
  ui_story_5040_50400701_7_dialog_content = "(ถึงกระนั้นเธอก็เชื่อมต่อกับ Eclipsites อย่างแน่นอน)",
  ui_story_5040_50400701_8_dialog_content = "(เธออยู่กับ Kya และไม่ได้สร้างปัญหาใดๆ ในตอนนี้ เราคงต้องรอดูกันต่อไป ฉันเดาว่า)",
  ui_story_5040_50400701_9_dialog_content = "คู่ซ้อม...คู่...?",
  ui_story_5040_50400701_10_dialog_content = "เธอไม่รู้วิธีต่อสู้! เกิดอะไรขึ้นถ้าเธอได้รับบาดเจ็บ?",
  ui_story_5040_50400701_11_dialog_content = "ใจเย็นๆ พวกเขาจะไม่ทะเลาะกันจริงๆ นี่เป็นเพียงเพื่อช่วยให้ Adonis ค้นหาความกล้าหาญของเขาเท่านั้น",
  ui_story_5040_50400701_12_dialog_content = "อิเหนาคิดยังไง?",
  ui_story_5040_50400701_13_dialog_content = "ฉัน- มันดูหยาบคายไปหน่อย... แต่ถ้าเซเบิลเต็มใจจะช่วย ฉันจะขอบคุณมาก",
  ui_story_5040_50400701_14_dialog_content = "ถ้าฉันต้องเผชิญหน้ากับ Eclipsite ในตอนนี้ ฉันแทบจะเสิร์ฟตัวเองบนจานสีเงิน",
  ui_story_5040_50400701_15_dialog_content = "ฉันไม่เก่งเรื่อง Luminatics เหมือนกัน เพราะฉันไม่ค่อยได้ใช้มัน โดยปกติแล้วฉันพึ่งธาราเพื่อปกป้องฉัน",
  ui_story_5040_50400701_16_dialog_content = "คุณไม่ต้องทำอย่างนี้ อิเหนา ทุกคนมีจุดแข็งและจุดอ่อนที่แตกต่างกัน",
  ui_story_5040_50400701_17_dialog_content = "และฉันไม่คิดว่าจะต้องปกป้องคุณให้เป็นภาระด้วยซ้ำ",
  ui_story_5040_50400701_18_dialog_content = "ธารา?",
  ui_story_5040_50400701_19_dialog_content = "ไม่...ไม่ว่ายังไงฉันต้องทำให้ได้! ฉันต้องผลักดันตัวเองออกจากโซนความสะดวกสบายของฉัน",
  ui_story_5040_50400701_20_dialog_content = "Kya, Sable ได้โปรดช่วยฉันด้วย!",
  ui_story_5040_50400701_21_dialog_content = "หืม... เซเบิล คุณโอเคกับเรื่องนี้ไหม?",
  ui_story_5040_50400701_22_dialog_content = "ถ้าหมายความว่า...ฉันช่วยได้...",
  ui_story_5040_50400701_23_dialog_content = "ถ้าอย่างนั้น... ฉันจะทำ!",
  ui_story_5040_50400701_24_dialog_content = "อย่ากดดันตัวเอง โอเค? มันเป็นแค่การต่อสู้ที่เสแสร้ง ไม่มีอะไรมากไปกว่านั้น",
  ui_story_5040_50400701_25_dialog_content = "ฉันจะไม่...",
  ui_story_5040_50400701_26_dialog_content = "ฉัน...ยินดีช่วย...",
  ui_story_5040_50400701_27_dialog_content = "คุณเก่งที่สุด เซเบิล!",
  ui_story_5040_50400701_28_dialog_content = "กรรรร! กรรรร!!",
  ui_story_5040_50400701_29_dialog_content = "เป็นแค่ฉันเองหรือว่าฉันได้ยินเสียงสุริยุปราคาจริงๆ...?",
  ui_story_5040_50400701_30_dialog_content = "หา?!",
  ui_story_5040_50400701_31_dialog_content = "<size=45>กร๊าาาา—!</size>",
  ui_story_5040_50400701_32_dialog_content = "ระวัง! มี Eclipsites ที่นี่!",
  ui_story_5040_50400701_33_dialog_content = "B-แต่ยังไงล่ะ! พวกเขามาจากไหน!",
  ui_story_5040_50400701_34_dialog_content = "ที่ไหนกันแน่? คุณและนกสีดำตัวเล็ก ๆ ของคุณดูเหมือนจะดึงดูดฝูงชนเสมอไม่ว่าคุณจะไปที่ไหน...",
  ui_story_5040_50400701_35_dialog_content = "มันอาจจะเป็นแค่เรื่องบังเอิญจริง ๆ เหรอ?",
  ui_story_5040_50400701_36_dialog_content = "อืมม",
  ui_story_5040_50400701_37_dialog_content = "(เซเบิลวาดสัตว์ประหลาดพวกนี้จริงๆ เหรอ...?)",
  ui_story_5040_50400701_38_dialog_content = "Eclip...ไซต์...?",
  ui_story_5040_50400701_39_dialog_content = "จุดสนใจ. มากำจัดศัตรูพืชเหล่านี้ก่อนอื่น",
  ui_story_5040_50400701_40_dialog_content = "ถอยไปข้างหลังอิเหนา!",
  ui_story_5040_50400701_41_dialog_content = "ฉันรู้",
  ui_story_5040_50400702_1_dialog_content = "ดูเหมือนว่าเราได้ทั้งหมด ทุกคนสบายดีไหม",
  ui_story_5040_50400702_2_dialog_content = "แน่นอน. มันเป็นเพียงไม่กี่ Eclipsites หลังจากนั้น",
  ui_story_5040_50400702_3_dialog_content = "ฉันก็สบายดีเหมือนกัน",
  ui_story_5040_50400702_4_dialog_content = "นั่นเป็นสิ่งที่ดีสำหรับคุณสาว ๆ แต่ดูเหมือนว่าจะเป็นคนละเรื่องกับสองคนนั้น",
  ui_story_5040_50400702_5_dialog_content = "อ๊ะ!",
  ui_story_5040_50400702_6_dialog_content = "ส...น่ากลัวจัง...",
  ui_story_5040_50400702_7_dialog_content = "(ฉันสงสัยว่าการมีสองคนนั้นฝึกกันจะมีประโยชน์แค่ไหน...)",
  ui_story_5040_50400702_8_dialog_content = "เราควรไปฝึกต่อดีไหม หรือคุณสองคนต้องการพัก?",
  ui_story_5040_50400702_9_dialog_content = "ฉันสามารถไปต่อได้!",
  ui_story_5040_50400702_10_dialog_content = "ม...ฉันด้วย...!",
  ui_story_5040_50400702_11_dialog_content = "อย่ากดดันตัวเอง เซเบิล",
  ui_story_5040_50400702_12_dialog_content = "เนื่องจากคุณทั้งคู่รู้สึกกล้าหาญ มาเริ่มกันเลย",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>15 นาทีต่อมา—</color>",
  ui_story_5040_50400702_14_dialog_content = "...",
  ui_story_5040_50400702_15_dialog_content = "...",
  ui_story_5040_50400702_16_dialog_content = "เอ่อ... พวกนายจะเริ่มเร็วๆ นี้เลยไหม? คุณยืนอยู่รอบ ๆ สักครู่แล้ว ...",
  ui_story_5040_50400702_17_dialog_content = "ฉันจะโจมตีเดี๋ยวนี้!",
  ui_story_5040_50400702_18_dialog_content = "...!!",
  ui_story_5040_50400702_19_dialog_content = "คุณดูไม่เหมือนกำลังจะออกรบเลย",
  ui_story_5040_50400702_20_dialog_content = "ฉันจะทำจริงๆ! คุณควรเตรียมตัวให้พร้อม!",
  ui_story_5040_50400702_21_dialog_content = "โอเค...!",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>หนึ่งชั่วโมงต่อมา...</color>",
  ui_story_5040_50400702_23_dialog_content = "คราวนี้ฉันสาบานว่าฉันจะโจมตี!",
  ui_story_5040_50400702_24_dialog_content = "แค่ดู!",
  ui_story_5040_50400702_25_dialog_content = "(ฉันง่วงมาก ฉันรู้สึกว่าฉันจะงีบหลับได้แล้ว)",
  ui_story_5040_50400702_26_dialog_content = "อย่างที่ฉันพูด Adonis คุณไม่จำเป็นต้องทำเช่นนี้จริงๆ",
  ui_story_5040_50400702_27_dialog_content = "โกเซเบิล!!!",
  ui_story_5040_50400702_28_dialog_content = "...",
  ui_story_5040_50400702_29_dialog_content = "คุณคิดว่า Eclipsite จะยืนอยู่รอบ ๆ เป็นเวลาหนึ่งชั่วโมงและรอให้คุณโจมตีหรือไม่?",
  ui_story_5040_50400702_30_dialog_content = "จำไว้ว่าคุณกำลังทำสิ่งนี้เพื่อเห็นแก่ทาร่า",
  ui_story_5040_50400702_31_dialog_content = "ถ้าเธอล้มลงในสนามรบและ Eclipsite มองเห็นเธอ คุณจะลังเลแบบนี้ไหม?",
  ui_story_5040_50400702_32_dialog_content = "คุณไม่จำเป็นต้องให้ฉันบอกคุณว่าผลลัพธ์จะเป็นอย่างไร",
  ui_story_5040_50400702_33_dialog_content = "ฉัน... ฉัน...",
  ui_story_5040_50400702_34_dialog_content = "หรือคุณกำลังบอกฉันว่าคุณไม่แคร์ถ้าเธอจะบาดเจ็บ เพราะคุณไม่เต็มใจที่จะก้าวข้ามความลังเลใจที่เกิดจากความขี้ขลาดของคุณ",
  ui_story_5040_50400702_35_dialog_content = "ท-นั่นไม่จริงเลย!",
  ui_story_5040_50400702_36_dialog_content = "แม้แต่ความลังเลเพียงชั่วครู่ก็อาจหมายถึงความแตกต่างระหว่างความเป็นกับความตาย ใครจะอยากอยู่กับคนที่ไม่น่าเชื่อถือ?",
  ui_story_5040_50400702_37_dialog_content = "<size=33>เฮ้! คุณรุกเขาแรงเกินไป!</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>ข้ารู้สึกแย่แทนเขาจริงๆ... เซเบิล ทำไมเจ้าไม่ช่วยเขาบ้างล่ะ?</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>เกร๋! กราาาาาา!</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>อ๊าาาา!!!</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>เงิบ...!</color>",
  ui_story_5040_50400702_42_dialog_content = "ฮ้า...ฮ้า...",
  ui_story_5040_50400702_43_dialog_content = "โอ๊ย...",
  ui_story_5040_50400702_44_dialog_content = "S-Sable! คุณสบายดีไหม?!",
  ui_story_5040_50400702_45_dialog_content = "ฉัน... ฉันไม่เป็นไร...",
  ui_story_5040_50400702_46_dialog_content = "เขาทำร้ายเธอจริงหรือ?",
  ui_story_5040_50400702_47_dialog_content = "คุณกำลังก้าวหน้า อิเหนา! อย่างน้อยคุณก็ไม่หลบอยู่ด้านหลัง!",
  ui_story_5040_50400702_48_dialog_content = "แน่นอนว่ามันเป็นการโจมตีที่เป็นอันตรายน้อยที่สุดที่ฉันเคยเห็นมาในชีวิต แต่ Caeleste นั้นพูดถูก",
  ui_story_5040_50400702_49_dialog_content = "ถึงกระนั้น คุณจะไม่ได้รับความนิยมใน Eclipsite จริงในเร็ว ๆ นี้",
