  ui_story_5040_50400702_168_dialog_content = "ฉันจะทำตามที่คุณขอเดี๋ยวนี้ ขอให้โชคดีนะคยา",
  ui_story_5040_50400702_169_dialog_content = "หมายความว่า...คุณกำลังช่วยฉัน?",
  ui_story_5040_50400702_170_dialog_content = "ขอบคุณ! ขอบคุณมากเลดี้ Jeriah",
  ui_story_5040_50400702_171_dialog_content = "และไม่ต้องกังวล! ไม่ว่าจะเกิดอะไรขึ้น ฉันจะรับผิดชอบอย่างเต็มที่จนถึงที่สุด",
  ui_story_5040_50400801_1_dialog_content = "เซเบิล ขอบคุณคุณ เราต้องทำบางสิ่งที่มีความหมายจริงๆ ในเมืองกันนอน กลับไปพักผ่อนกันเถอะ",
  ui_story_5040_50400801_2_dialog_content = "ได้สิ...",
  ui_story_5040_50400801_3_dialog_content = "คุณสบายดีไหม? ผิวของคุณดูไม่สดใส",
  ui_story_5040_50400801_4_dialog_content = "ใบหน้าของฉัน?",
  ui_story_5040_50400801_5_dialog_content = "ใช่. ฉันไม่ได้ตั้งใจจะหยาบคาย แต่คุณแค่ดูเหนื่อยๆ ก็พอแล้ว",
  ui_story_5040_50400801_6_dialog_content = "ช่วงนี้คุณได้รับวิตามินเพียงพอหรือไม่? หรือบางทีคุณอาจรู้สึกไม่สบายเล็กน้อย?",
  ui_story_5040_50400801_7_dialog_content = "ฉัน... ฉันไม่... คิดอย่างนั้น...",
  ui_story_5040_50400801_8_dialog_content = "กรรรร!",
  ui_story_5040_50400801_9_dialog_content = "แกร๊!!",
  ui_story_5040_50400801_10_dialog_content = "อะไร Eclipsites เพิ่มเติม?!",
  ui_story_5040_50400801_11_dialog_content = "นี่เป็นครั้งแรกที่ฉันเคยเห็นพวกมันในเมืองกันนอน!",
  ui_story_5040_50400801_12_dialog_content = "อ๊าาาาาาาา! ใครก็ได้ช่วยฉันที!!",
  ui_story_5040_50400801_13_dialog_content = "ฮ...เดี๋ยวก่อน...ฉัน!",
  ui_story_5040_50400801_14_dialog_content = "D-อย่า... กลัว...",
  ui_story_5040_50400801_15_dialog_content = "สีดำ! พาเด็กคนนั้นกลับไป!",
  ui_story_5040_50400802_1_dialog_content = "ต๊าย... คุณสองคนโอเคไหม?",
  ui_story_5040_50400802_2_dialog_content = "ช-ใช่ค่ะ",
  ui_story_5040_50400802_3_dialog_content = "ว้าว! Y-คุณดูน่ากลัวมาก!",
  ui_story_5040_50400802_4_dialog_content = "ฉัน...",
  ui_story_5040_50400802_5_dialog_content = "ไม่ต้องกังวลเกี่ยวกับเขา เซเบิล เด็กที่น่าสงสารอาจจะยังตกใจอยู่",
  ui_story_5040_50400802_6_dialog_content = "ถึงกระนั้น Eclipsites กำลังทำอะไรอยู่กลางเมืองกันนอน",
  ui_story_5040_50400802_7_dialog_content = "วุ้ย คุณสองคนช่วยฉันมาก!",
  ui_story_5040_50400802_8_dialog_content = "เจ-โจล่า?",
  ui_story_5040_50400802_9_dialog_content = "นี่เป็นหนึ่งใน Eclipsites ที่ Migard ใช้สำหรับการทดสอบ ด้วยเหตุผลบางอย่าง มันบ้าดีเดือดและหาทางออกจากห้องทดลองไม่ได้",
  ui_story_5040_50400802_10_dialog_content = "ขอบคุณพระเจ้าที่ไม่มีใครได้รับบาดเจ็บ... ขอบคุณคุณสองคน แน่นอน",
  ui_story_5040_50400802_11_dialog_content = "Eclipsite ใช้สำหรับการทดสอบ? คุณหมายถึงเหมือนของเมื่อวานใช่ไหม",
  ui_story_5040_50400802_12_dialog_content = "แม่นยำ. Migard จับ Eclipsites ได้ทุกชนิด ฉันไม่รู้แน่ชัดถึงลักษณะการทดลองของเธอ...",
  ui_story_5040_50400802_13_dialog_content = "แต่ดูเหมือนว่าเธอจะผ่าน Eclipsites ที่จับมาได้ค่อนข้างเร็ว",
  ui_story_5040_50400802_14_dialog_content = "!!!",
  ui_story_5040_50400802_15_dialog_content = "พวกนายต้องระวังตัวให้มากกว่านี้นะ! เกิดอะไรขึ้นถ้าสิ่งนี้สามารถทำร้ายใครบางคนได้?",
  ui_story_5040_50400802_16_dialog_content = "เรื่องแบบนี้ไม่เคยเกิดขึ้นมาก่อน อาจมีบางอย่างในตัวพวกคุณที่ดึงมันออกมา",
  ui_story_5040_50400802_17_dialog_content = "พูดถึง Sable เราอาจให้ Migard ดูคุณ เธอมียาทุกชนิดในห้องทดลองของเธอ",
  ui_story_5040_50400802_18_dialog_content = "หากคุณรู้สึกไม่สบาย ฉันแน่ใจว่าเธอสามารถช่วยได้!",
  ui_story_5040_50400802_19_dialog_content = "ไม่... ไม่ ขอบคุณ!",
  ui_story_5040_50400802_20_dialog_content = "ฉัน... เพิ่งนึกได้ว่า... มีบางอย่างที่สำคัญ!",
  ui_story_5040_50400802_21_dialog_content = "ฉันต้อง...ไป...ตามหา Kya!",
  ui_story_5040_50400802_22_dialog_content = "หา?!",
  ui_story_5040_50400802_23_dialog_content = "ฮี่ฮี่ฮี่... เจ้ามีเพื่อนที่น่าสนใจทีเดียว",
  ui_story_5040_50400802_24_dialog_content = "(เริ่มจะสายแล้ว... เซเบิลและคนอื่นๆ คงกำลังรอฉันอยู่ ฉันควรไปได้แล้ว)",
  ui_story_5040_50400802_25_dialog_content = "ค...คยา!!!",
  ui_story_5040_50400802_26_dialog_content = "สีดำ? คุณมาทำอะไรที่นี่? ไม่ควรอยู่ด้วย PlayerName ตอนนี้?",
  ui_story_5040_50400802_27_dialog_content = "อยาก...อยู่กับเธอ...คยา",
  ui_story_5040_50400802_28_dialog_content = "เข้าใจแล้ว...กลับกันเถอะ",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb>โครกก...</color>",
  ui_story_5040_50400802_30_dialog_content = "เมื่อกี้คืออะไร...?",
  ui_story_5040_50400802_31_dialog_content = "โอ้ว่า? ขออภัย นั่นเป็นเพียงท้องของฉัน",
  ui_story_5040_50400802_32_dialog_content = "ฉันไม่ได้กินอะไรเลยทั้งวัน ฉันกำลังหิวโหย!",
  ui_story_5040_50400802_33_dialog_content = "ม...ฉันด้วย...",
  ui_story_5040_50400802_34_dialog_content = "คุณด้วย? เอาล่ะ เราหาร้านอร่อยๆ ทานกันก่อนกลับคืนนี้",
  ui_story_5040_50400802_35_dialog_content = "เลขที่! ฉัน... ฉันดู... ผู้คนกำลัง... กลัว...",
  ui_story_5040_50400802_36_dialog_content = "สีดำ...?",
  ui_story_5040_50400802_37_dialog_content = "อย่าพูดอย่างนั้น คุณอาจดูไม่เหมือนกับชาวออโรเรียนส่วนใหญ่ แต่คุณก็ใจดีเหมือนเดิม",
  ui_story_5040_50400802_38_dialog_content = "เราสามารถซื้อขนมปังกลับบ้านได้ ฟังดูดีสำหรับคุณหรือไม่?",
  ui_story_5040_50400802_39_dialog_content = "ใช่แล้ว...",
  ui_story_5040_50400802_40_dialog_content = "สหพันธ์อิลลูมินาได้เตือนคุณถึงสิ่งอื่นหรือไม่ เซเบิล?",
  ui_story_5040_50400802_41_dialog_content = "เปล่านะ...",
  ui_story_5040_50400802_42_dialog_content = "ไม่เป็นไร! อย่างน้อยคุณก็จำทะเลทรายได้ใช่ไหม? ฉันพนันได้เลยว่าเราจะโชคดีขึ้นเมื่อไปถึงที่นั่น",
  ui_story_5040_50400802_43_dialog_content = "ไม่ต้องห่วง",
  ui_story_5040_50400802_44_dialog_content = "ขอบคุณนะ...",
  ui_story_5040_50400802_45_dialog_content = "อืม ฉันว่าฉันเห็นพ่อค้าขายขนมปังส้มอบเองข้างสถานีนะ รอฉันอยู่ที่นี่",
