  ui_story_5040_50400802_48_dialog_content = "ที่ฟังดู...คุ้นเคย...",
  ui_story_5040_50400802_49_dialog_content = "ฉันจะกลับมาเร็ว ๆ นี้ รอฉันที่นี่!",
  ui_story_5040_50400802_50_dialog_content = "อย่าไปไหนนะ ฉันจะกลับมาทันทีที่ซื้อมัน",
  ui_story_5040_50400802_51_dialog_content = "เอ็ดเวิร์ด พูดอะไรของเธอยาวจัง ทำไมคุณยังไม่กลับ",
  ui_story_5040_50400802_52_dialog_content = "ทำไมคุณไม่กลับมา",
  ui_story_5040_50400802_53_dialog_content = "เป็นเพราะฉันไม่ดีพอ? ทำไมทำไม?!",
  ui_story_5040_50400802_54_dialog_content = "<size=45>กลับมา!!!</size>",
  ui_story_5040_50400802_55_dialog_content = "รู้สึกสิ้นหวัง? ราวกับว่าไม่มีที่พึ่งใดในโลก? รับเมล็ดนี้แล้วคุณจะไม่ต้องกลัวอะไรอีกเลย",
  ui_story_5040_50400802_56_dialog_content = "ปลดปล่อยตัวเองจากความทุกข์ทรมานของผู้อ่อนแอ เพราะคุณจะแข็งแกร่งขึ้นกว่าที่คุณเคยจินตนาการได้!",
