  ui_story_5040_50400802_62_dialog_content = "เดี๋ยวก่อน...คุณแน่ใจหรือ? อาจจะเป็นอย่างอื่น...",
  ui_story_5040_50400802_63_dialog_content = "เราควรโทรหา Legion หรือไม่?",
  ui_story_5040_50400802_64_dialog_content = "!!!",
  ui_story_5040_50400802_65_dialog_content = "ไสหัวไปซะ!",
  ui_story_5040_50400802_66_dialog_content = "สีดำ? สีดำ! คุณสบายดีไหม?!",
  ui_story_5040_50400802_67_dialog_content = "อา...",
  ui_story_5040_50400802_68_dialog_content = "มาเลย เซเบิล! เราต้องออกไปจากที่นี่!",
