  ui_story_5040_50400802_74_dialog_content = "คุณบังเอิญเห็น Eclipsite หน้าตาประหลาดแถวๆ นี้หรือเปล่า? เธออยู่กับผู้หญิงคนหนึ่ง",
  ui_story_5040_50400802_75_dialog_content = "โอ้ ฟังดูน่าลำบากใจ ฉันเชื่อว่าพวกเขาพยายามหนีขึ้นสู่ผิวน้ำ... ฉันควรเรียกทหารมาเพิ่มไหม?",
  ui_story_5040_50400802_76_dialog_content = "อะไร พวกเขาไปถึงที่นั่นได้อย่างไร?! หลังจากที่พวกเขา!",
  ui_story_5040_50400802_77_dialog_content = "Jeriah... ขอบคุณ",
  ui_story_5040_50400802_78_dialog_content = "ดูเหมือนชายฝั่งจะใส คุณเจ็บไหม เซเบิล? ขอฉันดูหน่อย!",
  ui_story_5040_50400802_79_dialog_content = "ฉันสบายดี.",
  ui_story_5040_50400802_80_dialog_content = "ขอโทษที่...ทำให้เป็นห่วง...",
