  ui_story_5040_50400901_100_dialog_content = "ได้สิ...",
  ui_story_5040_50400901_101_dialog_content = "เข้าใจแล้ว!",
  ui_story_5040_50400901_102_dialog_content = "ยังไงก็ตาม ฉันควรจะไป ไม่งั้นอีฟจะรบกวนให้ฉันไปพักผ่อน",
  ui_story_5040_50400901_103_dialog_content = "ได้เลย แล้วเจอกัน!",
  ui_story_5040_50400901_104_dialog_content = "ตอนนี้ฉันไม่ควรไปหาเยรียาห์โดยตรง ก่อนอื่นฉันจะไปเติมที่อื่น",
  ui_story_5040_50400901_105_dialog_content = "ไม่ต้องพูดถึงฉันก็หิวด้วย! มาดูกันว่าวันนี้มีเมนูอะไรบ้าง!",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>ในขณะเดียวกัน ที่แผนก Courier Union Rediesel Wrench...</color>",
  ui_story_5040_50400901_107_dialog_content = "จดหมายที่ค้างทั้งหมดควรอยู่ที่นี่",
  ui_story_5040_50400901_108_dialog_content = "ด้วยทะเลทรายอันกว้างใหญ่และพวก Rediesel Wrench วิ่งไปทั่วทุกที่ จึงไม่แปลกใจเลยที่มีจดหมายที่ไม่มีผู้อ้างสิทธิ์จำนวนมาก",
  ui_story_5040_50400901_109_dialog_content = "อาจใช้เวลาสักครู่เพื่อค้นหาสิ่งที่เรากำลังมองหา",
  ui_story_5040_50400901_110_dialog_content = "เซเบิล...จะ...ช่วย...",
  ui_story_5040_50400901_111_dialog_content = "เราจะทำงานร่วมกัน! ก่อนอื่นเราต้องดูว่ามีตัวอักษรกี่ตัว",
  ui_story_5040_50400901_112_dialog_content = "มากมาย!",
  ui_story_5040_50400901_113_dialog_content = "เดี๋ยวก่อน พวกนี้มีโน้ตอยู่",
  ui_story_5040_50400901_114_dialog_content = "\"ไม่มีผู้รับ\" \"ไม่ทราบผู้รับ\" \"ถูกปฏิเสธ\"...",
  ui_story_5040_50400901_115_dialog_content = "พวกเขาทั้งหมดถูกยื่นภายใต้หมวดหมู่ที่แตกต่างกันหรือไม่!",
  ui_story_5040_50400901_116_dialog_content = "คยา... ดู... ตรงนั้น",
  ui_story_5040_50400901_117_dialog_content = "อันนี้บอก 'Small Stamp' ?!",
  ui_story_5040_50400901_118_dialog_content = "มีบางคำที่ขีดเขียนใต้ข้อความว่า \"สงสัยว่าคนส่งคือคนเดียวกัน\"",
  ui_story_5040_50400901_119_dialog_content = "ตราประทับที่นี่เหมือนกับของคุณ เซเบิล",
  ui_story_5040_50400901_120_dialog_content = "เหล่านี้...คือ...ของฉัน...",
  ui_story_5040_50400901_121_dialog_content = "ฉันไม่อยากเชื่อเลยว่าเราจะพบสิ่งที่เรากำลังมองหาอย่างรวดเร็ว ขอบคุณพระเจ้า!",
  ui_story_5040_50400901_122_dialog_content = "มาดูตัวอักษรกัน",
  ui_story_5040_50400901_123_dialog_content = "ใช่แล้ว...",
  ui_story_5040_50400901_124_dialog_content = "\"ขอบคุณที่ตกลงเป็นเพื่อนทางจดหมายของฉัน ยินดีที่ได้รู้จัก\"",
  ui_story_5040_50400901_125_dialog_content = "\"ทะเลทรายร้อนเกินไปสำหรับคนส่วนใหญ่ ดังนั้นทุกคนดูเหมือนจะอาศัยอยู่ห่างไกลกันมาก เราต้องพึ่งพาคนส่งของในการสื่อสาร\"",
  ui_story_5040_50400901_126_dialog_content = "\"ถ้าเราสามารถเดินทางด้วยกันได้ ฉันยินดีที่จะออกจากทะเลทราย\"",
  ui_story_5040_50400901_127_dialog_content = "จดหมายเหล่านี้ดูเหมือนจะเขียนขึ้นเมื่อคุณทำความรู้จักกับผู้รับเป็นครั้งแรก",
  ui_story_5040_50400901_128_dialog_content = "ที่อยู่ผู้รับจะแตกต่างกันเสมอ และไม่มีที่อยู่ผู้ส่ง",
  ui_story_5040_50400901_129_dialog_content = "บ้านของคุณอาจเคยอยู่ในทะเลทราย?",
  ui_story_5040_50400901_130_dialog_content = "อืม...",
  ui_story_5040_50400901_131_dialog_content = "อา!!",
  ui_story_5040_50400901_132_dialog_content = "สีดำ?!",
  ui_story_5040_50400901_133_dialog_content = "ฉันจำได้...",
  ui_story_5040_50400901_134_dialog_content = "บ้านของฉัน...ทะเลทรายลึก...",
  ui_story_5040_50400901_135_dialog_content = "แต่...ที่ไหน...จำไม่ได้...",
  ui_story_5040_50400901_136_dialog_content = "ไม่เป็นไร นี่เป็นโอกาสในการขายที่มีประโยชน์มากอยู่แล้ว ต่อไปเราต้องถามคนที่อาศัยอยู่ในทะเลทราย!",
  ui_story_5040_50400901_137_dialog_content = "อย่ากดดันตัวเองให้จำยากเกินไป พักก่อน",
  ui_story_5040_50400901_138_dialog_content = "ฉันยอมรับคำขอของคุณ ดังนั้นผู้จัดส่งในตัวฉันจะพยายามอย่างเต็มที่เพื่อช่วยเหลือคุณ",
  ui_story_5040_50400901_139_dialog_content = "ได้สิ...",
  ui_story_5040_50400901_140_dialog_content = "เกิดอะไรขึ้น เซเบิล? คุณดูกระสับกระส่ายเล็กน้อย",
  ui_story_5040_50400901_141_dialog_content = "ตาราอิเหนา...สายสัมพันธ์ดี...",
  ui_story_5040_50400901_142_dialog_content = "หวงแหน...กัน...ช่วยเหลือ...กัน...",
  ui_story_5040_50400901_143_dialog_content = "ฉันต้องการ...",
  ui_story_5040_50400901_144_dialog_content = "(เซเบิลไม่ได้รับการปฏิบัติที่ดีจากคนที่เธอรัก และความรักของเธอก็ไม่ได้รับการตอบสนอง)",
  ui_story_5040_50400901_145_dialog_content = "(เห็นสองคนนี้มีความสุขคงเศร้าใจ...)",
  ui_story_5040_50400901_146_dialog_content = "อย่ารู้สึกแย่ ผู้ชายคนนั้นที่ปฏิบัติกับคุณอย่างเลวร้ายนั้นกลายเป็นอดีตไปแล้ว!",
  ui_story_5040_50400901_147_dialog_content = "ผู้อาวุโสของฉันมักจะบอกฉันเสมอว่าจากประสบการณ์ของพวกเขา กรรมมักจะรับผู้ที่ปฏิบัติไม่ดีต่อผู้อื่นเสมอ",
  ui_story_5040_50400901_148_dialog_content = "สำหรับธาราและอิเหนา ถ้าการอยู่ใกล้พวกเขาทำให้คุณไม่พอใจ เราก็ออกไปจากที่นี่และเดินทางต่อได้",
  ui_story_5040_50400901_149_dialog_content = "ใช้ได้...",
  ui_story_5040_50400901_150_dialog_content = "พวกเขา... เตือนฉัน... เวลาแห่งความสุข...",
  ui_story_5040_50400901_151_dialog_content = "ครอบครัว... เพื่อน... ความรัก...",
  ui_story_5040_50400901_152_dialog_content = "ความรู้สึกอบอุ่นนั้น...คือทั้งหมดที่ฉันเคยต้องการ...",
  ui_story_5040_50400901_153_dialog_content = "ความอบอุ่นนั้น...มีค่า ฉันจึง... ขออวยพรให้...",
  ui_story_5040_50400901_154_dialog_content = "ได้สิ...",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>*รรัมเบิ้ล*</color>",
  ui_story_5040_50400901_156_dialog_content = "หิว...",
  ui_story_5040_50400901_157_dialog_content = "ฉันด้วย. ไปหาอะไรกินกันเถอะ!",
  ui_story_5040_50400901_158_dialog_content = "(ฉันไม่รู้ว่ามันดึกมากแล้ว และฉันก็ไม่รู้ว่าทาร่าและคนอื่นๆ กินข้าวเย็นกันยังไง)",
  ui_story_5040_50400901_159_dialog_content = "ฮัดเช่ย!",
  ui_story_5040_50400901_160_dialog_content = "(ท-รสฉุนเผ็ดนี้มีแต่...เรดดีเซลบาร์บีคิวเท่านั้น!)",
  ui_story_5040_50400901_161_dialog_content = "หืม? Kya, Sable, คุณสองคนเพิ่งสำรวจไม่ใช่เหรอ?",
  ui_story_5040_50400901_162_dialog_content = "เราทำเสร็จแล้ว และเนื่องจากเราหิวโหย เราจึงตัดสินใจที่จะกลับมาดูว่าอาหารเย็นกำลังดำเนินไปอย่างไร!",
  ui_story_5040_50400901_163_dialog_content = "ใช่แล้ว...",
  ui_story_5040_50400901_164_dialog_content = "(ฉันไม่รู้ว่าเมลค้างส่งถูกแยกและจัดหมวดหมู่แล้ว)",
  ui_story_5040_50400901_165_dialog_content = "(พวกเขาถูกจัดเข้าด้วยกันโดยผู้ส่งตามความคล้ายคลึงกันเล็กน้อย!)",
  ui_story_5040_50400901_166_dialog_content = "(ต้องขอบคุณเท่านั้นที่เราหาจดหมายของ Sable ได้อย่างรวดเร็ว)",
  ui_story_5040_50400901_167_dialog_content = "(ฉันคิดว่านั่นคือเยรียาห์ทั้งหมด)",
  ui_story_5040_50400901_168_dialog_content = "แถวนี้คึกคักแน่นอน",
  ui_story_5040_50400901_169_dialog_content = "กลิ่นนั้น...ฮา พวก Rediesel Wrench ของคุณเท่านั้นที่รู้วิธีทำบาร์บีคิวไฟ ใช่มั้ย?",
  ui_story_5040_50400901_170_dialog_content = "เมื่อคุณอยู่ในทะเลทราย คุณจะกินเหมือนคนในทะเลทราย",
  ui_story_5040_50400901_171_dialog_content = "คุณทำทุกอย่างเสร็จแล้วเหรอ Jeriah?",
  ui_story_5040_50400901_172_dialog_content = "ใช่. รถและเสบียงพร้อมแล้ว และฉันก็ระบุระยะที่หนอนทรายออกหากินด้วย",
  ui_story_5040_50400901_173_dialog_content = "มันได้รับบาดเจ็บจากการโจมตีครั้งก่อน ดังนั้นมันจึงมุ่งหน้าลึกเข้าไปในทะเลทราย",
  ui_story_5040_50400901_174_dialog_content = "(ซึ่งสอดคล้องกับที่ซินซาบอกฉัน)",
  ui_story_5040_50400901_175_dialog_content = "(ไม่พูดอะไรดีกว่า เผื่อ Jeriah จะหงุดหงิดอีก...)",
  ui_story_5040_50400901_176_dialog_content = "จังหวะเหมาะ! กิ้งก่ากระตุกพร้อมแล้ว มาทานกัน!",
  ui_story_5040_50400901_177_dialog_content = "นี่เป็นไม้เสียบจริงๆเหรอ? คุณไม่สามารถเห็นอะไรภายใต้พริกทั้งหมด",
  ui_story_5040_50400901_178_dialog_content = "สิ่งนี้เรียกว่าจิ้งจกกระตุกเผ็ดมาก มีเพียงนักผจญภัยด้านอาหารที่กล้าหาญที่สุดเท่านั้นที่กล้าลิ้มรสสุดยอดของอาหาร Rediesel",
  ui_story_5040_50400901_179_dialog_content = "เอ่อ ฉันต้อง?",
  ui_story_5040_50400901_180_dialog_content = "พริกเยอะมาก แค่มองก็แสบตาแล้ว",
  ui_story_5040_50400901_181_dialog_content = "คุณจะมีบ้างหรือไม่?",
  ui_story_5040_50400901_182_dialog_content = "ใช่! แน่นอนฉันเป็น",
  ui_story_5040_50400901_183_dialog_content = "อย่าบังคับตัวเองอิเหนา",
  ui_story_5040_50400901_184_dialog_content = "*ง่ำ*",
  ui_story_5040_50400901_185_dialog_content = "...",
  ui_story_5040_50400901_186_dialog_content = "เขา- เขากินหมดในครั้งเดียว?",
  ui_story_5040_50400901_187_dialog_content = "...!",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>พลัก!</color>",
  ui_story_5040_50400901_189_dialog_content = "เอ-อิเหนา?!",
  ui_story_5040_50400901_190_dialog_content = "ฮ่าๆๆๆ ดูนั่นสิ! เขากลายเป็นสีม่วงไปหมดแล้ว!",
  ui_story_5040_50400901_191_dialog_content = "เผ็ด...",
  ui_story_5040_50400901_192_dialog_content = "<size=45>เผ็ดมาก!!</size>",
  ui_story_5040_50400901_193_dialog_content = "ว้าว เขาเหมือนกำลังจะเป็นลม!",
  ui_story_5040_50400901_194_dialog_content = "เร็วเข้า ใครก็ได้จับนมเขาที! ฉันได้ยินมาว่านมนั้นดีต่ออาหารรสจัด!",
  ui_story_5040_50400901_195_dialog_content = "ฉันจะไปดู!",
  ui_story_5040_50400901_196_dialog_content = "...",
  ui_story_5040_50400901_197_dialog_content = "(เธอไปทำไม ฉันจะไปดูว่าเกิดอะไรขึ้น)",
  ui_story_5040_50400901_198_dialog_content = "เจอนมแล้ว!",
  ui_story_5040_50400901_199_dialog_content = "อิเหนา ดื่มนี่สิ!",
  ui_story_5040_50400901_200_dialog_content = "*อึ๊ก อึ๊ก อึ๊ก*",
  ui_story_5040_50400901_201_dialog_content = "อา... อา... ฉันยังหายใจอยู่ไหม...?",
  ui_story_5040_50400901_202_dialog_content = "คุณเพิ่งกินจิ้งจกกระตุกรสเผ็ดจัดเสียบไม้จนหมด",
  ui_story_5040_50400901_203_dialog_content = "จริงเหรอ",
  ui_story_5040_50400901_204_dialog_content = "อึก... ปวดท้องเหมือนกลืนก้อนถ่านที่ลุกโชนเข้าไป...",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>อุ๊ย!</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "อิเหนา?!!",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>ขณะเดียวกัน...</color>",
  ui_story_5040_50400901_208_dialog_content = "แฟนตัวน้อยของคุณกำลังสำรอกสมองออกมาทางนั้น คุณจะไม่ไปดูว่าเขาสบายดีไหม?",
  ui_story_5040_50400901_209_dialog_content = "หรือคุณมีความคิดที่สดใสอื่น ๆ ?",
  ui_story_5040_50400901_210_dialog_content = "ฉันจะพา Adonis กลับ Northland ทันทีที่เขาฟื้น",
  ui_story_5040_50400901_211_dialog_content = "ฉันเหนื่อย. ฉันไม่ต้องการทำสิ่งนี้อีกต่อไป",
  ui_story_5040_50400901_212_dialog_content = "เราไม่ได้เกิดมาคู่กัน เราเข้ากันไม่ได้",
  ui_story_5040_50400901_213_dialog_content = "งั้นเหรอ",
  ui_story_5040_50400901_214_dialog_content = "ฉันเคยคิดว่าตราบใดที่เราอยู่ด้วยกัน เราจะเอาชนะทุกสิ่งได้",
  ui_story_5040_50400901_215_dialog_content = "ฉันอยากจะให้เขาได้ลิ้มรสชีวิตในทะเลทราย Rediesel เหมือนบาร์บีคิวเมื่อกี้นี้...",
  ui_story_5040_50400901_216_dialog_content = "แต่ฉันไม่เคยคิดว่าสิ่งที่ฉันชอบจะทำให้เขาเสียหาย",
  ui_story_5040_50400901_217_dialog_content = "เขาเจ็บอยู่เรื่อย ๆ เพราะเขาบังคับตัวเองให้สนใจฉัน",
  ui_story_5040_50400901_218_dialog_content = "ฉันไม่คิดว่านั่นคือความรัก",
  ui_story_5040_50400901_X218_dialog_content = "เฮ้อ...เบอร์ดี้กำลังมีความรักจะข้ามไปสู่บทสรุปทุกประเภทในเรื่องเล็กน้อยอย่างแน่นอน",
  ui_story_5040_50400901_X219_dialog_content = "ทำไมคิดแบบนั้นล่ะ?",
  ui_story_5040_50400901_219_dialog_content = "มีเพียงช่องว่างระหว่างเราไม่ว่าจะเป็นวิถีชีวิตหรือบุคลิกภาพ บางทีพ่อแม่ของเขาพูดถูก",
  ui_story_5040_50400901_220_dialog_content = "นกแดนเหนือขาดขนที่บางและไม่รู้วิธีขุดหาน้ำ ดังนั้นแน่นอนว่าพวกมันไม่สามารถอยู่รอดได้ในทะเลทราย",
  ui_story_5040_50400901_221_dialog_content = "...",
  ui_story_5040_50400901_222_dialog_content = "นี่ไม่ใช่สิ่งที่ความกล้าหาญจะเอาชนะได้ เป็นเรื่องของความแตกต่างโดยกำเนิด",
  ui_story_5040_50400901_223_dialog_content = "สิ่งที่พบได้ทั่วไปสำหรับนกทะเลทรายนั้นเป็นอันตรายต่อนกทางเหนือ",
  ui_story_5040_50400901_224_dialog_content = "แต่กลับ...",
  ui_story_5040_50400901_225_dialog_content = "แต่อะไรเหรอ",
  ui_story_5040_50400901_226_dialog_content = "เจ้านกน้อยของคุณกินของเผ็ดไม่ได้ แต่ก็ยังเอาไม้เสียบลงไปกินอยู่ดี และลงไปกองกับพื้น",
  ui_story_5040_50400901_227_dialog_content = "แน่นอนเขาต้องการแสดงให้คุณเห็นว่าเขาเต็มใจที่จะก้าวขึ้นและกล้าหาญหรือไม่?",
  ui_story_5040_50400901_228_dialog_content = "ค่อยๆ หาไลฟ์สไตล์ที่เหมาะกับคุณทั้งคู่",
  ui_story_5040_50400901_229_dialog_content = "แทนที่จะจำกัดตัวเองให้อยู่แต่กับไลฟ์สไตล์ของ Rediesel",
  ui_story_5040_50400901_230_dialog_content = "...!",
  ui_story_5040_50400901_231_dialog_content = "นั่นคือทั้งหมดที่ฉันอยากจะพูด",
  ui_story_5040_50400901_232_dialog_content = "ไม่ว่าคุณสองคนจะลงเอยด้วยกันหรือไม่ คุณก็อยู่ที่นี่แล้ว ดังนั้นคุณก็อาจจะสนุกไปกับมันได้เช่นกัน",
