  ui_story_5040_50400901_234_dialog_content = "...",
  ui_story_5040_50400901_235_dialog_content = "อืมม",
  ui_story_5040_50400901_236_dialog_content = "ฉันกำลังจะกลับ",
  ui_story_5040_50400901_237_dialog_content = "ช่างเป็นนกตัวเล็ก ๆ ที่น่าสนใจ",
  ui_story_5040_50400901_238_dialog_content = "ฉันอยากรู้ว่าบทต่อไปของความสัมพันธ์ของคุณจะเป็นอย่างไร",
  ui_story_5040_50400901_239_dialog_content = "... ฮะ เกิดอะไรขึ้นกับฉัน?",
  ui_story_5040_50400901_240_dialog_content = "ฉันไม่อยากจะเชื่อเลยว่าฉันยังห่วงใย",
  ui_story_5040_50401001_1_dialog_content = "อา มาแล้วเหรอ?",
  ui_story_5040_50401001_2_dialog_content = "เราตกลงที่จะมองหาหนอนทรายในวันนี้ ดังนั้นฉันจึงตื่นแต่เช้าเป็นพิเศษ",
  ui_story_5040_50401001_3_dialog_content = "แถมไม่มีใครกล้ากินด้วย ก็เลยต้องไปหาอะไรกินที่ Soroz...",
  ui_story_5040_50401001_4_dialog_content = "พวกคุณไม่ชอบอาหารที่ดี แต่ไม่ต้องห่วง ฉันกินบาร์บีคิวที่เหลือแล้ว",
  ui_story_5040_50401001_5_dialog_content = "กัดไม่เสียสักคำ!",
