  ui_story_5040_50401001_7_dialog_content = "แล้วเมื่อคืนทุกคนนอนกันยังไง?",
  ui_story_5040_50401001_8_dialog_content = "ผมเองก็นอนหลับอย่างน่าอัศจรรย์",
  ui_story_5040_50401001_9_dialog_content = "ในทะเลทรายตอนกลางคืนนั้นหนาวเย็น แต่โชคดีที่คุณเตรียมผ้าห่มหนาๆ มาให้ ฉันกับเซเบิลก็สบายดี",
  ui_story_5040_50401001_10_dialog_content = "ขอบคุณ...",
  ui_story_5040_50401001_11_dialog_content = "โอ้ ไม่มีปัญหาเลย เซเบิล",
  ui_story_5040_50401001_12_dialog_content = "ฉัน เอ่อ...",
  ui_story_5040_50401001_13_dialog_content = "ปวดท้องทั้งคืน...",
  ui_story_5040_50401001_14_dialog_content = "(น่าจะเป็น Adonis ที่ฉันได้ยินว่าวิ่งไปห้องน้ำหลายครั้งเมื่อคืนนี้)",
  ui_story_5040_50401001_15_dialog_content = "คุณต้องการที่จะพักผ่อนสักหน่อยก่อนที่จะออกไป?",
  ui_story_5040_50401001_16_dialog_content = "ฉันไม่เป็นไร!",
  ui_story_5040_50401001_17_dialog_content = "ฉันไม่เป็นไรจริงๆ!",
  ui_story_5040_50401001_18_dialog_content = "...",
  ui_story_5040_50401001_19_dialog_content = "(ทาร่ามีสีหน้าขบขันตั้งแต่มื้อค่ำเมื่อคืนนี้ เธอคิดอะไรอยู่หรือเปล่า?)",
  ui_story_5040_50401001_20_dialog_content = "ใช้ได้. ในกรณีนี้ไปกันเลย ธาราสามารถมีที่นั่งผู้โดยสารและส่วนที่เหลือของคุณนั่งด้านหลัง",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>หลังจากนั้นซักพัก...</color>",
  ui_story_5040_50401001_22_dialog_content = "ใกล้กับบริเวณทะเลทรายลึกซึ่งเป็นที่อยู่ของหนอนทราย",
  ui_story_5040_50401001_23_dialog_content = "มาพักผ่อนกันที่นี่",
  ui_story_5040_50401001_24_dialog_content = "ฉันย้ายเต็นท์ อุปกรณ์ทำอาหาร และอาหารทั้งหมดลงจากรถกับ Sable",
  ui_story_5040_50401001_25_dialog_content = "เราสามารถเริ่มทำอาหารได้ตลอดเวลา!",
  ui_story_5040_50401001_26_dialog_content = "ดีมาก",
