  ui_story_5040_50401001_30_dialog_content = "เนินทรายข้างหน้าสูงชันและลาดเอียง การขี่คลื่นทรายเป็นวิธีที่สมบูรณ์แบบในการปลดปล่อยและผ่อนคลาย",
  ui_story_5040_50401001_31_dialog_content = "เนินทรายเกี่ยวอะไรกับการพักผ่อน?",
