  ui_story_5040_50401001_X33_dialog_content = "แต่มัน...",
  ui_story_5040_50401001_X34_dialog_content = "เลิกพูดตะกุกตะกักแล้วขึ้นรถซะ!",
  ui_story_5040_50401001_X35_dialog_content = "คุณสามารถมาด้วย Caelesti น้อย",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>ในรถ</color>",
  ui_story_5040_50401001_X37_dialog_content = "ทุกคนสบายดีไหม?",
