  ui_story_5040_50401001_39_dialog_content = "อ๊าาา!",
  ui_story_5040_50401001_40_dialog_content = "T-นี่มันเร็วเกินไป!",
  ui_story_5040_50401001_41_dialog_content = "วู้ฮู! นี่มันเจ๋งมาก!",
