  ui_story_5040_50401002_8_dialog_content = "ฉันวางแผนที่จะทำขนมสไตล์ Umbraton แต่ตอนนี้ทุกอย่างกลับหัวกลับหาง ใช้ไม่ได้โดยสิ้นเชิง!",
