  ui_story_5040_50401002_14_dialog_content = "ฉันไม่แน่ใจว่าเราจะใช้มันกับสิ่งที่คุณวางแผนไว้ได้ไหม แต่เราสามารถปรุงสตูว์ได้แน่นอน",
