  ui_story_5040_50401002_44_dialog_content = "(เธอแกล้งทำเป็นสูญเสียความทรงจำซึ่งทำให้ฉันต้องออกจากนอร์ธแลนด์... ทั้งหมดนี้อาจเป็นอุบายที่ทำให้ฉันกล้าหาญมากขึ้น?)",
