  ui_story_5040_50401002_132_dialog_content = "นั่นเป็นเพราะฉันเป็นหนึ่งในคนส่งของเพียงไม่กี่คนในทะเลทรายที่สามารถส่งข้อมูลที่พวกเขาต้องการได้",
  ui_story_5040_50401002_133_dialog_content = "มันไม่ใช่อย่างนั้นนะครับ!",
  ui_story_5040_50401002_134_dialog_content = "เอาล่ะ ฉันคิดว่าฉันพักผ่อนเพียงพอแล้ว",
  ui_story_5040_50401002_135_dialog_content = "เฮ้ เยริอาห์!",
  ui_story_5040_50401002_136_dialog_content = "เก็บสิ่งของของคุณเข้าด้วยกัน ได้เวลาออกเดินทางแล้ว",
  ui_story_5040_50401002_137_dialog_content = "อย่างจริงจัง Jeriah แค่เดินออกไปแล้วปล่อยให้ฉันห้อย ทำไมคุณไม่...",
  ui_story_5040_50401002_138_dialog_content = "เธอมีนิสัยชอบปฏิเสธและแสร้งทำเป็นว่าทุกอย่างเรียบร้อยดีหรือไม่?",
  ui_story_5040_50401101_1_dialog_content = "การเตรียมตัวของคุณเป็นอย่างไร นกน้อย?",
  ui_story_5040_50401101_2_dialog_content = "ฉันพร้อมแล้วที่จะไปทุกเมื่อ",
  ui_story_5040_50401101_3_dialog_content = "ฉันพร้อมแล้ว",
  ui_story_5040_50401101_4_dialog_content = "ไฟดับแล้ว และเรามีข้าวของทั้งหมด",
  ui_story_5040_50401101_5_dialog_content = "คุณฉลาดมาก Kya!",
  ui_story_5040_50401101_6_dialog_content = "ขอบคุณ! เอเมอรัลด์สอนฉันเป็นอย่างดี",
  ui_story_5040_50401101_7_dialog_content = "มรกตคือใคร?",
  ui_story_5040_50401101_8_dialog_content = "เธอเป็นรุ่นพี่ของฉันที่ Courier Union แม้ว่าตอนนี้เธอจะเกษียณแล้วก็ตาม",
  ui_story_5040_50401101_9_dialog_content = "ก่อนที่ฉันจะเป็นคนส่งเอกสาร Emerald เป็นผู้ส่งจดหมายไปยัง Faar บ้านเกิดของฉันและหมู่บ้านใกล้เคียงอื่นๆ",
  ui_story_5040_50401101_10_dialog_content = "บ้านเกิดของฉันห่างไกลมาก แทบไม่ได้ติดต่อกับโลกภายนอกเลย",
  ui_story_5040_50401101_11_dialog_content = "ทางเดียวของเราที่จะรู้ว่าเกิดอะไรขึ้นคือผ่านจดหมายที่ Emerald ส่งมา",
  ui_story_5040_50401101_12_dialog_content = "เธอต้องเป็นคนที่มีความรับผิดชอบจริงๆ",
  ui_story_5040_50401101_13_dialog_content = "โอ้ใช่! เป็นเพราะเธอที่ทำให้ฉันกลายเป็นคนส่งของ!",
  ui_story_5040_50401101_14_dialog_content = "ฉันรู้โดยตรงว่าผู้คนที่อาศัยอยู่ในสถานที่ห่างไกลนั้นยากเพียงใดในการติดต่อกับโลกภายนอก ฉันจึงอยากเป็นสะพานเชื่อมให้ผู้อื่นออกสู่ภายนอก",
  ui_story_5040_50401101_15_dialog_content = "ที่น่าตื่นตาตื่นใจ!",
  ui_story_5040_50401101_16_dialog_content = "ฮิฮิ ฉันยังมีที่ว่างสำหรับการปรับปรุง",
  ui_story_5040_50401101_17_dialog_content = "แม้จะมีโน้ตทั้งหมดที่ Emerald ให้ฉัน ฉันก็ยังทำมันพัง...",
  ui_story_5040_50401101_18_dialog_content = "แม้ว่าฉันจะทำตามคำแนะนำทั้งหมดในบันทึกของเธออย่างแม่นยำ แต่สิ่งต่าง ๆ มักจะแตกต่างไปจากที่ฉันคาดไว้เสมอ",
  ui_story_5040_50401101_19_dialog_content = "คุณไม่จำเป็นต้องทำตามคำแนะนำแบบนั้นเสมอไป บางครั้งก็จำเป็นต้องด้นสดและปรับให้เข้ากับสถานการณ์",
  ui_story_5040_50401101_20_dialog_content = "เอ่อ ฉันไม่เก่งเรื่องนั้นหรอก",
  ui_story_5040_50401101_21_dialog_content = "กรรรรรรรรรร!!",
  ui_story_5040_50401101_22_dialog_content = "คุณได้ยินไหม? บางสิ่งบางอย่างในระยะไกล?",
  ui_story_5040_50401101_23_dialog_content = "นั่นมัน...?",
  ui_story_5040_50401101_24_dialog_content = "อ๊ากกก! กรร!",
  ui_story_5040_50401101_25_dialog_content = "สุริยุปราคา! ทุกคนระวัง!",
  ui_story_5040_50401101_26_dialog_content = "หลายคน!",
  ui_story_5040_50401101_27_dialog_content = "คราวนี้ไปเอามาจากไหน!",
  ui_story_5040_50401101_28_dialog_content = "กลุ่มอื่น? แปลกแค่ไหน...",
  ui_story_5040_50401101_29_dialog_content = "เรามาจัดการกับพวกเขาก่อน ขอให้โชคดีและระมัดระวัง",
  ui_story_5040_50401102_1_dialog_content = "กรรรร!",
  ui_story_5040_50401102_2_dialog_content = "แปลก พวกเขามักจะไม่ยอมแพ้ง่ายๆ แต่พวกเขาก็วิ่งหนีไป...",
  ui_story_5040_50401102_3_dialog_content = "นี่ไม่ใช่พื้นที่ที่มักปรากฏ Eclipsites",
  ui_story_5040_50401102_4_dialog_content = "แต่นี่เป็นกลุ่มที่สองที่เราพบในสองสามวันที่ผ่านมา นั่นไม่ใช่เรื่องปกติ",
  ui_story_5040_50401102_5_dialog_content = "พวกเขากำลัง... วิ่ง...",
  ui_story_5040_50401102_6_dialog_content = "พูดอะไรน่ะ",
  ui_story_5040_50401102_7_dialog_content = "เซเบิลบอกว่าดูเหมือนพวกเขากำลังวิ่งหนี ซ่อนตัวจากอะไรบางอย่าง?",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>ครืนนน...</color>",
  ui_story_5040_50401102_9_dialog_content = "พื้นดินสั่นสะเทือนหรือไม่?",
  ui_story_5040_50401102_10_dialog_content = "หลีกทางครับทุกท่าน มีบางอย่างกำลังมา!",
  ui_story_5040_50401102_11_dialog_content = "ธารา ระวัง!",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>รัว!</size>",
  ui_story_5040_50401102_14_dialog_content = "ว้าว!! ฉ- นั่นหนอนทรายสีชมพูจริงๆเหรอ?!",
  ui_story_5040_50401102_15_dialog_content = "ฉันคิดว่ามันควรจะมุ่งหน้าไปยังส่วนลึกของทะเลทราย! นั่นเอ่อค่อนข้างไกลจากที่นี่!",
  ui_story_5040_50401102_16_dialog_content = "มีอีกหนึ่งคำอธิบายสำหรับรูปลักษณ์ของมัน... มันอาจจะเป็นเวลาให้อาหาร",
  ui_story_5040_50401102_17_dialog_content = "คุณกำลังบอกว่ามันพยายามกิน Eclipsites พวกนั้นเหรอ?",
  ui_story_5040_50401102_18_dialog_content = "ใช่... และดูเหมือนว่าตอนนี้เรากำลังอยู่ในเมนู",
  ui_story_5040_50401102_19_dialog_content = "<size=50>รัว!</size>",
  ui_story_5040_50401102_20_dialog_content = "ทำไมรีบร้อนผู้ชายตัวใหญ่?",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>ตูม—!</color>",
  ui_story_5040_50401102_22_dialog_content = "นั่นคือเกราะบาง!",
  ui_story_5040_50401102_23_dialog_content = "ฮี่ฮี่... ข้าเดาว่าเกล็ดสีชมพูพวกนั้นแข็งแกร่งกว่าที่เห็นมาก",
