  ui_story_5040_50401102_26_dialog_content = "โรอา—",
  ui_story_5040_50401102_27_dialog_content = "ดูสิ มันได้ผล!",
  ui_story_5040_50401102_28_dialog_content = "ฉันจะช่วยด้วย!",
