  ui_story_5040_50401102_40_dialog_content = "มันพยายามทำให้เราผิดหวังโดยการลากการต่อสู้ออกไป!",
  ui_story_5040_50401102_41_dialog_content = "เราปล่อยให้สิ่งนั้นเกิดขึ้นไม่ได้ Grimoire ปลดปล่อยพลังของคุณ!",
