  ui_story_5040_50401401_52_dialog_content = "เราไม่เห็นนาง... เมื่อไปถึง เราพบเพียงท่านและอิเหนาเป็นลมหมดสติไป ฉันก็ไม่รู้สึกว่าเธออยู่ใกล้ ๆ เช่นกัน ...",
  ui_story_5040_50401401_53_dialog_content = "คุณจำได้ไหมว่าเกิดอะไรขึ้นก่อนที่คุณจะหมดสติ?",
  ui_story_5040_50401401_54_dialog_content = "ฉัน... ฉันจำได้แค่ว่าพายุทรายถูกปล่อยขึ้นไปบนท้องฟ้าพร้อมกับเซเบิล... ฉันคิดว่าเธอสามารถคว้าเขาของหนอนทรายได้",
  ui_story_5040_50401401_55_dialog_content = "หลังจากนั้น หนอนทรายก็ลากพวกเราลงใต้ดิน และหัวฉันก็โขกหินหรืออะไรซักอย่าง... หลังจากนั้นทุกอย่างก็ดำมืด",
  ui_story_5040_50401401_56_dialog_content = "ถ้าทั้งคุณและ Adonis หมดสติไปทั้งคู่... ใครกันที่ซ่อนคุณสองคนไว้ที่นี่?",
  ui_story_5040_50401401_57_dialog_content = "เว้นเสียแต่ว่า...",
  ui_story_5040_50401401_58_dialog_content = "สีดำ?!",
  ui_story_5040_50401401_59_dialog_content = "แต่ถ้าเธอเป็นคนที่ซ่อนคุณไว้ที่นี่ ทำไมเธอถึงไม่มีใครเห็น?",
  ui_story_5040_50401401_60_dialog_content = "บางทีเธออาจต้องการล่อหนอนทรายให้ห่างจาก Kya และ Adonis? หรือบางที...",
  ui_story_5040_50401401_61_dialog_content = "เธอรู้สึกว่าเธอถึงขีดจำกัดแล้ว",
  ui_story_5040_50401401_62_dialog_content = "“ลิมิต”? “จำกัด” อะไร? คุณสองคนเป็นอะไรกันในเวลานี้?",
  ui_story_5040_50401401_63_dialog_content = "ความจริงก็คือ เซเบิลไม่ใช่ชาวออโรเรียน หรือว่าเธอเคยเป็นคนหนึ่ง",
  ui_story_5040_50401401_64_dialog_content = "อะไรนะ!",
  ui_story_5040_50401401_65_dialog_content = "ฉันรู้แล้วล่ะ...",
  ui_story_5040_50401401_66_dialog_content = "คุณดูไม่แปลกใจเลย Caeleste",
  ui_story_5040_50401401_67_dialog_content = "ฉันมีลางสังหรณ์ว่าเป็นเช่นนั้น ฉันแค่ไม่เคยมีหลักฐาน...",
  ui_story_5040_50401401_68_dialog_content = "เธอถูกคนรักทิ้งไปตั้งแต่เธอยังเป็นชาวออโรเรียน ในความสิ้นหวังของเธอ เธอถูกดึงไปสู่พลังของ Eclipsites และกลายเป็น Sable ที่เรารู้จักในตอนนี้",
  ui_story_5040_50401401_69_dialog_content = "แม้ว่าร่างกายและจิตใจของเธอจะได้รับผลกระทบอย่างหนัก แต่จิตสำนึกของเธอยังคงต่อสู้เพื่อต่อต้านการกระตุ้นให้ต่อสู้และทำลายล้าง",
  ui_story_5040_50401401_70_dialog_content = "อย่างไรก็ตาม ไม่นานมานี้ เธอบอกกับฉันว่าเธอทนไม่ได้อีกต่อไปแล้ว...",
  ui_story_5040_50401401_71_dialog_content = "มันคือเรื่องอะไรกันนะ...?",
  ui_story_5040_50401401_72_dialog_content = "(ทำไมรู้สึกเหมือนเคยเจอเรื่องแบบนี้มาก่อน...?)",
  ui_story_5040_50401401_73_dialog_content = "บอกฉัน, PlayerName. คุณคิดว่าเซเบิ้ลเป็นคนแบบไหน?",
  ui_story_5040_50401401_74_option_content = "หนึ่งที่ดี",
  ui_story_5040_50401401_75_dialog_content = "เธออาจดูและทำตัวแตกต่างออกไปเล็กน้อย แต่เธอก็เป็นมิตรกับทุกคน ฉันเชื่อว่าเธอเป็นคนดี",
