  ui_story_5040_50401401_78_dialog_content = "เธอดูขี้อายจริงๆ เลยไม่ค่อยได้คุยกัน... แต่นั่นไม่ได้ทำให้ฉันไม่เชื่อว่าเธอเป็นคนดี!",
