  ui_story_5040_50401401_104_dialog_content = "ฉันคิดว่ามันถึงเวลาแล้วที่เราจะเปลี่ยนภัยคุกคามสีชมพูนี้แทน... พร้อมแล้ว Caeleste ตัวน้อย?",
