  ui_story_5040_50401402_4_dialog_content = "ก่อนที่คนส่งจดหมายจะนำจดหมายมาให้ฉัน ฉันคิดว่าฉันเป็นเพียงคนธรรมดาที่ไม่มีใครในโลก",
  ui_story_5040_50401402_5_dialog_content = "แต่จดหมายฉบับนั้นทำให้ฉันได้เห็นความสวยงามของโลกนอกทะเลทราย... และทำให้ฉันได้พบกับ \"เขา\" ได้อย่างไร...",
